packages/kit/src/signpage/messages.ts.body:
// The signing page's postMessage API (wallet.md §7 item 4; app.md §2.1 A2-A4). The app talks to SIGN_HOST's hidden
// iframe only with these messages, the origin checked both ways. Every request kind has its wallet.md §2.8 row; the
// page refuses a kind with no row, a field its row does not allow, and a `v` other than 1. Answers and events carry
// addresses, balances, tx hashes and states only: never a key, the 12 words, a note secret or a signed-but-unsent
// payload (wallet.md §2.9 row 11).
//
// Every amount is a decimal string. A request's `id` is crypto.randomUUID(); a retry reuses it, and the page answers a
// repeated id with its first answer, never a second run, so a timeout and a retry can never buy twice.

import type { Chain, OrderTrigger } from "../orders/record.ts";

/**
 * The twenty-one request kinds, app to page. nav and reload are to SIGN_HOST's shell (card signpage-shell); the last four
 * are the pool kinds (card signpage-pool-kinds), added after kit-v1 without changing any other kind.
 */
export const SIGNPAGE_KINDS = [
  "deposit.quote",
  "deposit.confirm",
  "arm",
  "buy",
  "hop",
  "orders.set",
  "orders.cancel",
  "return",
  "withdraw.open",
  "signin.open",
  "backup.open",
  "export.open",
  "signout",
  "restore",
  "state",
  "nav",
  "reload",
  "pool.deposit",
  "pool.buy",
  "pool.sell",
  "pool.withdraw",
] as const;

export type SignpageKind = (typeof SIGNPAGE_KINDS)[number];

/** The kinds that open a SIGN_HOST top-level screen: the app posts one, then moves the same tab to SIGN_HOST. */
export const OPEN_KINDS = ["withdraw.open", "signin.open", "backup.open", "export.open", "signout", "pool.withdraw"] as const satisfies readonly SignpageKind[];

/** The chains a pool runs on: NEAR's money is the vault's, never a pool's. */
export type PoolChain = "solana" | "base" | "robinhood";
export const POOL_CHAINS: readonly PoolChain[] = Object.freeze(["solana", "base", "robinhood"] as const);

/** The events, page to app. */
export const SIGNPAGE_EVENTS = ["ready", "state", "progress"] as const;

export type SignpageEventType = (typeof SIGNPAGE_EVENTS)[number];

/** The way in for sign-in. */
export type SigninWay = "passkey" | "words" | "wallet";

/**
 * Where SIGN_HOST sends the tab back once a top-level flow ends: a key from the fixed list in the release (for example
 * "deposit", "withdraw", "settings", "position"). SIGN_HOST maps it to an APP_HOST URL; the URL never carries it.
 */
export type ReturnKey = string;

interface Open {
  return_key: ReturnKey;
}

/** The params of each kind, spread into the request envelope next to v, id and type. */
export interface SignpageParams {
  /** Ask a deposit address for money from outside: the 1Click asset id the user sends, and how much of it. */
  "deposit.quote": { origin_asset: string; amount: string };
  /** Read the state of a deposit by the address the quote answered. Signs nothing. */
  "deposit.confirm": { deposit_address: string };
  /** Get fresh wallets ready on a chain for the amount in the trade box. Answered at once; runs in the background. */
  arm: { chain: Chain; amount: string };
  /**
   * A trade by hand from fresh wallets: a buy spends `amount` of USDC from the ready set, a sell sells `amount` of the
   * token from the wallets that hold it. `slippage_bps` is the user's, within the release's control ranges.
   */
  buy: { chain: Chain; token: string; side: "buy" | "sell"; amount: string; slippage_bps: number };
  /** Move money from a ready wallet on one chain to a fresh wallet on another. */
  hop: { from: Chain; to: Chain; amount: string };
  /**
   * Sign the exits of a position in advance: a take-profit and a stop, each with its trigger price and the share of
   * the position it sells, in basis points.
   */
  "orders.set": {
    chain: Chain;
    token: string;
    slippage_bps: number;
    tp?: { trigger_price: string; share_bps: number };
    sl?: { trigger_price: string; share_bps: number };
  };
  /** Cancel orders by id. */
  "orders.cancel": { order_ids: string[] };
  /** Send what a fresh wallet holds back to the vault. */
  return: { chain: Chain; wallet: string };
  /** Open the withdraw form; with `from_id`, the move out of a one-time id or an arming account. The address is typed there. */
  "withdraw.open": Open & { from_id?: string };
  /** Open the sign-in for one way in. */
  "signin.open": Open & { way: SigninWay };
  /** Open the backup screen. */
  "backup.open": Open;
  /** Open the key export for one wallet of this seed. */
  "export.open": Open & { chain: Chain; address: string };
  /** Open sign-out (the backup first when the 12 words are not saved yet). */
  signout: Open;
  /** Rebuild the store from the chain. Signs nothing; reports `progress` at least every 10 s. */
  restore: Record<never, never>;
  /** Read the state. Signs nothing. */
  state: Record<never, never>;
  /**
   * Where the app is now: its path and query on APP_HOST. The shell puts it in the top window's address with
   * history.replaceState and never navigates, so the address bar, a reload and a shared link follow the app. A path
   * that is not APP_HOST's own path and query, or over SIGNPAGE_MAX_NAV_BYTES of UTF-8, is refused not_allowed.
   */
  nav: { path: string };
  /** Reload the top window: the shell and the app in it (a reload of the frame alone would keep the old shell). */
  reload: Record<never, never>;
  /** Move `amount` of the chain pool's asset (POOL_ASSET_DECIMALS) that the device holds on that chain into the pool. */
  "pool.deposit": { chain: PoolChain; amount: string };
  /** A release from the chain's pool to a fresh wallet that buys `token` with `amount` of the pool's asset. */
  "pool.buy": { chain: PoolChain; token: string; amount: string; slippage_bps: number };
  /** The fresh wallet sells `amount` of `token`; the proceeds go back into the chain's pool in the same transaction. */
  "pool.sell": { chain: PoolChain; token: string; amount: string; slippage_bps: number };
  /** Open SIGN_HOST's withdraw screen for the chain's pool. The address is typed there, never sent by the app. */
  "pool.withdraw": Open & { chain: PoolChain };
}

export interface TxRef {
  chain: Chain;
  hash: string;
}

/** A top-level flow is set up: the page wrote its one-use pending-flow record. Its outcome comes back in `state`. */
export interface OpenResult {
  pending: true;
}

/** The result of each kind. */
export interface SignpageResults {
  "deposit.quote": {
    deposit_address: string;
    origin_asset: string;
    amount_in: string;
    min_amount_out: string;
    /** ISO 8601: send before it. */
    deadline: string;
    time_estimate_s: number;
  };
  "deposit.confirm": { stage: DepositStage };
  arm: { stage: "queued" };
  /** Answered once every slice is signed and sent; the fill comes in `progress`. */
  buy: { stage: TradeStage; txs: TxRef[] };
  hop: { stage: HopStage; txs: TxRef[] };
  "orders.set": { orders: { order_id: string; group_id: string; kind: OrderTrigger["kind"]; state: OrderState }[] };
  "orders.cancel": { orders: { order_id: string; state: OrderState }[]; txs: TxRef[] };
  return: { stage: ReturnStage; txs: TxRef[] };
  "withdraw.open": OpenResult;
  "signin.open": OpenResult;
  "backup.open": OpenResult;
  "export.open": OpenResult;
  signout: OpenResult;
  restore: { stage: "started" };
  state: SignpageState;
  nav: Record<never, never>;
  reload: Record<never, never>;
  "pool.deposit": { stage: TradeStage; txs: TxRef[] };
  "pool.buy": { stage: TradeStage; txs: TxRef[] };
  "pool.sell": { stage: TradeStage; txs: TxRef[] };
  "pool.withdraw": OpenResult;
}

/**
 * Why a request was refused: "not_allowed" (no wallet.md §2.8 row allows it), "quote_check_failed" (a quote failed the
 * device's checks), or a trade check's id from the markets paper.
 */
export type ErrorCode = "not_allowed" | "quote_check_failed" | (string & {});

export type SignpageRequest<K extends SignpageKind = SignpageKind> = {
  [P in K]: { v: 1; id: string; type: P } & SignpageParams[P];
}[K];

export type SignpageAnswer<K extends SignpageKind = SignpageKind> =
  | { v: 1; id: string; ok: true; result: SignpageResults[K] }
  | { v: 1; id: string; ok: false; error: { code: ErrorCode } };

/** The handshake: the first message the page posts once it listens. `api` is this file's version. */
export interface ReadyEvent {
  v: 1;
  type: "ready";
  /** The signing page's release tag, the one APP_HOST's build pins with its index.html sha384. */
  release: string;
  api: 1;
}

/** Posted on every change of the state. */
export interface StateEvent {
  v: 1;
  type: "state";
  state: SignpageState;
}

/** The stage of a request still running, by its id. */
export interface ProgressEvent {
  v: 1;
  type: "progress";
  id: string;
  stage: Stage;
}

export type SignpageEvent = ReadyEvent | StateEvent | ProgressEvent;

/** Anything the page posts to the app. */
export type SignpageMessage = SignpageAnswer | SignpageEvent;

export type DepositStage = "quote_checked" | "waiting" | "in_transit" | "into_vault" | "done" | "refunded" | "held" | "halted";
export type WithdrawStage = "proving" | "submitted" | "in_transit" | "sent" | "refunded" | "stopped";
export type TradeStage = "signed" | "sent" | "filled" | "part_filled" | "refused" | "not_landed";
export type HopStage = "in_flight" | "arrived" | "refunded" | "fallback";
export type ReturnStage = "signed" | "sent" | "in_transit" | "into_vault" | "done";
export type RestoreStage = "started" | "reading" | "done" | "stalled";
export type Stage = DepositStage | WithdrawStage | TradeStage | HopStage | ReturnStage | RestoreStage | "queued";

/** The assets a chain's pool holds. A pool's asset comes from the device's own pool table, never from a server. */
export type PoolAsset = "SOL" | "ETH" | "USDC";
export const POOL_ASSETS: readonly PoolAsset[] = Object.freeze(["SOL", "ETH", "USDC"] as const);
/** Each pool asset's decimals: the one table. state.pools carries no decimals; an amount's 1.0 is 10^decimals here. */
export const POOL_ASSET_DECIMALS: Readonly<Record<PoolAsset, number>> = Object.freeze({ SOL: 9, ETH: 18, USDC: 6 });

export type WalletState = "PLANNED" | "ARMING" | "READY" | "IN_POSITION" | "RETURNING" | "EMPTY";
export type OrderState = "SIGNED" | "ARMED" | "FILLED" | "CANCELLED" | "DEAD";

export type Operation =
  | { id: string; kind: "deposit"; stage: DepositStage; txs: TxRef[] }
  | { id: string; kind: "withdraw"; stage: WithdrawStage; txs: TxRef[] }
  | { id: string; kind: "buy" | "sell"; stage: TradeStage; txs: TxRef[]; code?: ErrorCode }
  | { id: string; kind: "hop"; stage: HopStage; txs: TxRef[] }
  | { id: string; kind: "return"; stage: ReturnStage; txs: TxRef[] }
  | { id: string; kind: "restore"; stage: RestoreStage; txs: TxRef[] };

/** What the page tells the app: addresses, balances, tx hashes and states only. */
export interface SignpageState {
  /** The signing page's release tag. */
  release: string;
  api: 1;
  signed_in: boolean;
  way?: SigninWay;
  /** False while the 12 words are the only copy and not saved: the backup comes before the first deposit. */
  code_saved: boolean;
  /** The last way in that failed on SIGN_HOST, and why (for example "no_prf", "no_passkey"). */
  signin_failed?: { way: SigninWay; reason: string };
  /** USDC in the vault. */
  vault_balance: string;
  /**
   * The private balance held in each chain's pool, read from the device's own notes (never from a server): one entry
   * per chain, each amount a decimal string in whole units of the pool's asset, as vault_balance is for USDC (12.5 SOL
   * is "12.5"). `asset` is the pool's, set by the device from the pool's kind; its decimals are POOL_ASSET_DECIMALS's
   * alone. `ready` is how much of it is ready to buy (chunks with a proof ready); absent while no proof
   * queue runs, never "0" in its place. Absent when the page is signed out or the notes could not be read. Totals
   * only, never a note; the app sees them each time the store changes, so two in a row can show one note's value.
   */
  pools?: { chain: Chain; asset: PoolAsset; balance: string; ready?: string }[];
  wallets: { chain: Chain; address: string; role: "fresh" | "hop"; size: string; state: WalletState }[];
  positions: { chain: Chain; token: string; amount: string; cost: string; wallets: string[] }[];
  orders: {
    order_id: string;
    chain: Chain;
    wallet: string;
    token: string;
    group_id: string;
    trigger: OrderTrigger;
    state: OrderState;
    /** Unix ms of the last check of its nonce. */
    last_check?: number;
  }[];
  /** Money held under a one-time id or an arming account whose arm has stopped; withdraw.open with the id moves it. */
  held: { id: string; asset: string; amount: string }[];
  ops: Operation[];
}

packages/kit/src/orders/record.ts.body:
// The order record: what the device sends the order sender for each order it signs in advance (wallet.md §7 item 3,
// in the shape of markets.md H5.1; decided 2026-11-01 00:35Z). POST /v1/orders carries one group of one or two
// records. Each exit sells from the fresh wallet W, its output goes to W itself, and min_out is fixed inside the signed
// bytes, so a server that holds this record can only send the order early, at the user's price or better
// (wallet.md §2.6).

/** The chains a fresh wallet trades on. */
export type Chain = "solana" | "base" | "robinhood" | "near";

export const CHAINS = ["solana", "base", "robinhood", "near"] as const satisfies readonly Chain[];

/** What fires an order. */
export interface OrderTrigger {
  kind: "stop" | "take_profit" | "limit";
  /** The pool whose price the order sender reads. */
  pool: string;
  /** The venue (the program or contract family) that pool belongs to. */
  venue: string;
  /** "lte" fires when the price falls to `price` or below (a stop), "gte" when it rises to it or above. */
  direction: "lte" | "gte";
  /** Decimal string: the token's price, in `quote_asset` per whole token, at which the order fires. */
  price: string;
  /** The asset `price` is counted in, in the chain's own form. */
  quote_asset: string;
}

/**
 * The nonce every variant of an order and its twin share, so the first to land makes all the others invalid
 * (wallet.md §2.6). Integers are decimal strings.
 */
export interface NonceRefs {
  /** A durable nonce: the nonce account and the nonce value stored in it. */
  solana: { nonce_account: string; nonce_value: string };
  base: { wallet: string; nonce: string };
  robinhood: { wallet: string; nonce: string };
  /** The access key's nonce: nonces are per key on NEAR. */
  near: { account: string; public_key: string; nonce: string };
}

export type NonceRef = NonceRefs[Chain];

export interface OrderRecord<C extends Chain = Chain> {
  v: 1;
  /** 16 random bytes the device picks, lowercase hex. */
  order_id: string;
  /** Links an order to its twin (a stop and its take-profit): groups of 1 or 2. Same form as order_id. */
  group_id: string;
  chain: C;
  /** The fresh wallet W that signed it, in the chain's own address form. */
  wallet: string;
  /** The token sold, in the chain's own form (a base58 mint, a lowercase 0x address, a NEAR account id). */
  token: string;
  /** Integer string: the amount of the token sold, in its base units; the same in every variant. */
  amount: string;
  /** Integer string: the least the sell pays W, in the native coin's base units; the same in every variant's bytes. */
  min_out: string;
  trigger: OrderTrigger;
  nonce_ref: NonceRefs[C];
  /**
   * 1 to 3 signed variants of the same sell at rising fees, all on `nonce_ref`, so only one can land: base64 of the
   * signed transaction (Solana, EVM) or the signed NEP-366 delegate (NEAR), byte for byte as the device signed it.
   */
  variants: [string] | [string, string] | [string, string, string];
  /** NEAR only: the block height at which the delegates expire (their `max_block_height`). */
  expires_at?: C extends "near" ? number : never;
}

/**
 * The record's fields, exactly: a receiver refuses a record with any other field. On the wire, POST /v1/orders adds
 * only token_hash (helper/v1.ts HELPER_ORDER_FIELDS).
 */
export const ORDER_RECORD_FIELDS = [
  "v",
  "order_id",
  "group_id",
  "chain",
  "wallet",
  "token",
  "amount",
  "min_out",
  "trigger",
  "nonce_ref",
  "variants",
  "expires_at",
] as const satisfies readonly (keyof OrderRecord)[];

/** At most this many signed variants per order. */
export const ORDER_VARIANTS_MAX = 3;

packages/kit/src/helper/v1.ts.body:
// The helper API /v1, frozen with the kit on Nov 1 06:00Z: every path of markets.md H7 with its 7.1 changes
// (research main 3dbe87c). It is what the kit, the signing page and any outside wallet, terminal or bot call on a
// helper: ours, or their own copy of it.
// Types and constants only. It imports only the kit's own order record (Chain, OrderRecord and ORDER_RECORD_FIELDS,
// never redefined here) and signs nothing; a helper holds API keys, never a money key, and can only carry what the device signed. Nothing a
// helper answers is trusted for anything signed: the device checks every answer against its own request and its own
// chain reads before it signs.
// Wire rules: JSON bodies; a signed transaction or delegate in standard base64; an intent's public key and signature
// as ed25519:<base58> (intents.near's raw_ed25519 form, HelperSignedIntent); no cookies; the kit calls with HELPER_FETCH_INIT; every
// answer carries X-Helper-Commit. An error is { error: { code } } with the HTTP status of HELPER_CODE_STATUS (400 for
// a code not listed there). Limits are design values (H7: "Limits are [design]").

import { ORDER_RECORD_FIELDS, type Chain, type OrderRecord } from "../orders/record.ts";

// ---------------------------------------------------------------------------------------------------------------
// Common
// ---------------------------------------------------------------------------------------------------------------

export const HELPER_V1_PREFIX = "/v1";

/** On every answer, errors included: the helper's own commit. */
export const HELPER_COMMIT_HEADER = "X-Helper-Commit";
/** On every /v1/proxy answer: the vendor it came from, and when the helper read it. */
export const HELPER_SOURCE_HEADER = "X-Helper-Source";
export const HELPER_FETCHED_AT_HEADER = "X-Fetched-At";

/** The kit's fetch settings for every helper call. */
export const HELPER_FETCH_INIT = { credentials: "omit", referrerPolicy: "no-referrer" } as const;

/**
 * Cross-origin reads (H7 "Cross-origin reads", 7.1 row "every path, and the push socket"). Access-Control-Allow-Origin
 * is the request's Origin only when it equals one of `origins` byte for byte (scheme, host and port), and absent for
 * any other, null included; never "*". It and Vary: Origin are on every answer, errors included.
 * Access-Control-Allow-Credentials is never sent, on any answer (`allowCredentialsHeader: "absent"`; markets.md:3300). A preflight (OPTIONS with Access-Control-Request-Method) from one of `origins`
 * answers 204 with exactly `allowMethods`, `allowHeaders` and `maxAgeSeconds`; one asking any other header, or from any
 * other origin, gets no allow headers. The push socket checks Origin on the upgrade: one of `origins` passes, any other
 * gets 403, and an upgrade with no Origin (not a browser) passes. A call with no Origin (a server or a bot) is answered
 * as any other.
 * `origins` are this release's APP_HOST and SIGN_HOST; a helper run by someone else lists its own two.
 */
export const HELPER_CORS = {
  origins: ["https://confidential.unrealized.trade", "https://sign.confidential.unrealized.trade"],
  allowMethods: ["GET", "POST", "PUT", "DELETE"],
  allowHeaders: ["content-type"],
  // Retry-After: a device reads a 429's wait cross-origin (card wallet-per-buy, M367)
  exposeHeaders: ["X-Helper-Commit", "X-Helper-Source", "X-Fetched-At", "Retry-After"],
  maxAgeSeconds: 600,
  vary: "Origin",
  allowCredentialsHeader: "absent",
} as const;

/** Standard base64 of bytes the device signed; a helper carries them byte for byte. */
export type HelperBase64 = string;
/** A non-negative integer as a canonical decimal string (no sign, no leading zero): u128 and U256 amounts. */
export type HelperDecimal = string;
/** A NEAR account id. */
export type HelperNearAccount = string;
/** A NEAR public key: "ed25519:" and the 32-byte key in base58. */
export type HelperNearPublicKey = `ed25519:${string}`;
/** An ed25519 signature: "ed25519:" and the 64 bytes in base58 (never base64). */
export type HelperEd25519Signature = `ed25519:${string}`;
/** A transaction id in its chain's form. */
export type HelperTxHash = string;

/** The parts of /v1/health, one per value of H7's Part column (7.1 row "GET /v1/health parts"). */
export const HELPER_PARTS = ["proxy", "relay", "intents", "delegate", "orders", "log"] as const;
export type HelperPart = (typeof HELPER_PARTS)[number];

/** Codes any path can answer: a vendor or RPC down (H2.3), a body over its limit, a full bucket (H2.2), no such thing. */
export const HELPER_COMMON_CODES = ["upstream", "too_large", "rate_limited", "not_found"] as const;
export type HelperCommonCode = (typeof HELPER_COMMON_CODES)[number];

export interface HelperError<C extends string> {
  error: { code: C | HelperCommonCode };
}
export type HelperAnswer<T, C extends string> = T | HelperError<C>;

/** The HTTP status of each code that does not answer 400. */
export const HELPER_CODE_STATUS = {
  not_found: 404,
  token_not_watched: 404,
  too_large: 413,
  rate_limited: 429,
  id_not_ours: 403,
  sender_struck: 403,
  receiver_is_vault: 403,
  prepay_open: 409,
  not_paid: 409,
  receiver_not_registered: 409,
  upstream: 503,
  token_halted: 503,
  index_behind: 503,
  relayer_low: 503,
} as const;

// ---------------------------------------------------------------------------------------------------------------
// The paths (H7's table and 7.1's new rows), with their part and body limit in bytes
// ---------------------------------------------------------------------------------------------------------------

export const HELPER_V1_PATHS = [
  { method: "GET", path: "/v1/health", part: "all", limitBytes: 1024 },
  { method: "POST", path: "/v1/proxy/{vendor}/{path}", part: "proxy", limitBytes: 65536 },
  { method: "POST", path: "/v1/rpc/{chain}", part: "proxy", limitBytes: 262144 },
  { method: "GET", path: "/v1/market/...", part: "proxy", limitBytes: null },
  { method: "GET", path: "/v1/logo/{chain}/{token}", part: "proxy", limitBytes: 262144 },
