// One call from the device's leaves to a withdraw proof made in the prover worker (card vault-prover-e2e; the vault
// paper's rows V2.4 and V2.6, docs/plan1/vault.md l.1198 and l.1200, and the kit's call in l.1284: prove(inputs) ->
// {proof, publicSignals} in snarkjs JSON, in one same-origin worker, single thread).
//
// - The inputs are vaultWithdrawInput's (../vault/inputs.ts). It refuses, before any proof, a tree whose root is not
//   the vault's newest (a changed, missing or extra leaf), a note whose commitment or label is not in its tree, and
//   every withdrawal the vault would refuse. So a refused call never posts a prove to the worker.
// - The worker (client.ts, worker.js) loads the withdraw setup files once per Prover and checks each by sha256.
// - The worker's answer is checked here before the caller gets it: its public signals must be exactly the 8 this input
//   gives, computed apart from the circuit (Withdraw(32)'s outputs newCommitmentHash = Poseidon(value - withdrawn,
//   label, Poseidon(newNullifier, newSecret)) and existingNullifierHash = Poseidon(existingNullifier), commitment.circom
//   l.24-36 and withdraw.circom l.17-43 of Privacy Pools v1.3.0, then the input's public values, in
//   VAULT_WITHDRAW_SIGNALS order), and its proof must be in the affine form the vault parses (vaultProof). An answer
//   that differs is refused, so the proof the device hands on carries the roots, amount and context of its own request.
// - The pairing check is the vault's, with its compiled key: the page carries no verifier. prove-e2e.test.ts checks
//   the worker's proofs with snarkjs and the release's withdraw.vkey.
// Nothing here logs: the input holds the note's secrets.
import { poseidon1 } from "poseidon-lite/poseidon1";
import { poseidon2 } from "poseidon-lite/poseidon2";
import { poseidon3 } from "poseidon-lite/poseidon3";
import { poolWithdrawInput, type PoolWithdrawInputArgs, vaultWithdrawInput, type VaultWithdrawInput, type VaultWithdrawInputArgs } from "../vault/inputs.ts";
import { VAULT_WITHDRAW_SIGNALS, vaultProof, type VaultSnarkjsProof, type VaultWithdrawSignals } from "../vault/shapes.ts";
import type { Prover } from "./client.ts";

/** The worker's load and prove (startProver in client.ts gives one). */
export type VaultProver = Pick<Prover, "load" | "prove">;

/** A withdraw proof, its public signals in snarkjs order, and fullProve's own time in the worker, in ms. */
export type VaultWithdrawProof = { proof: VaultSnarkjsProof; publicSignals: VaultWithdrawSignals; proveMs: number };

// one load of the withdraw setup files per prover; a failed load is dropped, so the next call tries again
const loads = new WeakMap<VaultProver, Promise<void>>();
function loadWithdraw(prover: VaultProver): Promise<void> {
  const had = loads.get(prover);
  if (had) return had;
  const load = prover.load("withdraw");
  loads.set(prover, load);
  load.catch(() => {
    if (loads.get(prover) === load) loads.delete(prover);
  });
  return load;
}

/** The 8 public signals Withdraw(32) gives for this input, in snarkjs order. */
function signalsOf(i: VaultWithdrawInput): VaultWithdrawSignals {
  const left = BigInt(i.existingValue) - BigInt(i.withdrawnValue);
  const newCommitmentHash = poseidon3([left, BigInt(i.label), poseidon2([BigInt(i.newNullifier), BigInt(i.newSecret)])]);
  const existingNullifierHash = poseidon1([BigInt(i.existingNullifier)]);
  return [
    String(newCommitmentHash),
    String(existingNullifierHash),
    i.withdrawnValue,
    i.stateRoot,
    i.stateTreeDepth,
    i.ASPRoot,
    i.ASPTreeDepth,
    i.context,
  ];
}

/**
 * Proves the withdrawal of `args.withdrawn` from `args.note` in the prover worker, from the leaves the device holds
 * (`args.stateTree`, `args.labelTree`) against the vault's newest roots. Throws what vaultWithdrawInput refuses before
 * any proof, and refuses a worker answer whose public signals are not this input's or whose proof is not well formed.
 */
export async function vaultProveWithdraw(prover: VaultProver, args: VaultWithdrawInputArgs): Promise<VaultWithdrawProof> {
  return proveInput(prover, vaultWithdrawInput(args));
}

/**
 * The same for a spend in any pool on this circuit, with the context the pool's own context function gave
 * (poolWithdrawInput): the answer's 8 public signals must be this input's, its context the pool's.
 */
export async function poolProveWithdraw(prover: VaultProver, args: PoolWithdrawInputArgs): Promise<VaultWithdrawProof> {
  return proveInput(prover, poolWithdrawInput(args));
}

async function proveInput(prover: VaultProver, input: VaultWithdrawInput): Promise<VaultWithdrawProof> {
  const want = signalsOf(input);
  await loadWithdraw(prover);
  const got: unknown = await prover.prove("withdraw", input);
  const r = (got ?? {}) as { proof?: unknown; publicSignals?: unknown; proveMs?: unknown };
  const signals = r.publicSignals;
  if (!Array.isArray(signals) || signals.length !== want.length) throw new Error(`worker answer: not ${want.length} public signals`);
  want.forEach((w, k) => {
    if (signals[k] !== w) throw new Error(`worker answer: ${VAULT_WITHDRAW_SIGNALS[k]} is not the input's`);
  });
  try {
    vaultProof(r.proof as VaultSnarkjsProof);
  } catch (e) {
    throw new Error(`worker answer: ${e instanceof Error ? e.message : "proof: not snarkjs JSON"}`);
  }
  const proveMs = typeof r.proveMs === "number" && Number.isFinite(r.proveMs) ? r.proveMs : NaN;
  return { proof: r.proof as VaultSnarkjsProof, publicSignals: want, proveMs };
}

packages/kit/src/prover/client.ts.body:
// The prover's page side (vault.md 2.14, row V2.4), for SIGN_HOST only: APP_HOST's policy never allows
// 'wasm-unsafe-eval', so a prover there fails closed (M304 D-8; wallet.md 2.7). It starts the one same-origin worker,
// prover-worker.js (build.mjs), through the Trusted Types policy `prover-worker`, which turns exactly that one URL into a
// TrustedScriptURL and refuses every other (SIGN_HOST's CSP: require-trusted-types-for 'script'; trusted-types
// prover-worker). It fetches each setup file from its own origin at /assets/zk/<sha256>.<ext> (zk/setup-files.ts),
// always asking the server (cache "no-cache": SIGN_HOST caches the files immutable, so a file that once came back wrong
// under its pinned name would otherwise be read from the browser's cache at every retry; a right one costs a 304), and
// moves the bytes to the worker by transfer, so no copy stays here; the worker checks every file's size and sha256
// before snarkjs sees it (worker.js), and proves on its threads (worker.js, card signpage-prover-threads).
import { ZK_SETUP_FILES } from "../zk/setup-files.ts";
import type { VaultSnarkjsProof } from "../vault/shapes.ts";

export const PROVER_POLICY_NAME = "prover-worker";
/** Every refusal of a worker that died or was ended starts with this; such a worker answers nothing again. */
export const PROVER_DEAD_PREFIX = "prover worker: ";

/** True when `e` is the refusal of a dead or ended prover worker: start a new one to prove again. */
export function isProverDead(e: unknown): boolean {
  return e instanceof Error && e.message.startsWith(PROVER_DEAD_PREFIX);
}
export const PROVER_WORKER_PATH = "/prover-worker.js";

export type ProverCircuit = "withdraw" | "commitment";
export type ProverInput = Readonly<Record<string, string | readonly string[]>>;
export interface ProverResult {
  proof: VaultSnarkjsProof;
  publicSignals: string[];
  /** fullProve's own time in the worker, in ms. */
  proveMs: number;
}
export interface ProverViolation {
  directive: string;
  blocked: string;
  sample: string;
}
export interface Prover {
  /** Fetches the circuit's wasm and zkey and moves them to the worker, which refuses them unless both match their pins. */
  load(circuit: ProverCircuit): Promise<void>;
  prove(circuit: ProverCircuit, input: ProverInput): Promise<ProverResult>;
  terminate(): void;
}
export interface ProverOptions {
  /** CSP or Trusted Types violations the worker reports. */
  onViolation?: (v: ProverViolation) => void;
}

/** The setup file's address on the page's own origin. */
export function setupFileURL(name: "withdraw.wasm" | "withdraw.zkey" | "commitment.wasm" | "commitment.zkey", origin: string): string {
  const ext = name.slice(name.lastIndexOf(".") + 1);
  return new URL(`/assets/zk/${ZK_SETUP_FILES[name].sha256}.${ext}`, origin).href;
}

type ScriptURLPolicy = { createScriptURL(input: string): unknown };
let policy: ScriptURLPolicy | null = null;

/**
 * The worker's script URL made through the policy `prover-worker`, created once per page (the CSP names it without
 * 'allow-duplicates'). The policy throws on anything but this origin's PROVER_WORKER_PATH. In a browser without
 * Trusted Types the plain URL is returned, as nothing there checks a sink.
 */
export function proverWorkerScriptURL(): string | object {
  const origin = self.location.origin;
  const url = new URL(PROVER_WORKER_PATH, origin).href;
  const tt = (self as unknown as { trustedTypes?: { createPolicy(n: string, r: { createScriptURL(s: string): string }): ScriptURLPolicy } }).trustedTypes;
  if (!tt) return url;
  policy ??= tt.createPolicy(PROVER_POLICY_NAME, {
    createScriptURL(input: string): string {
      const u = new URL(input, self.location.origin);
      if (u.href !== url || u.origin !== self.location.origin) throw new TypeError(`${PROVER_POLICY_NAME} refuses ${u.href}`);
      return u.href;
    },
  });
  return policy.createScriptURL(url) as object;
}

type Reply = { id: number; ok: true; value: unknown } | { id: number; ok: false; error: string } | { type: "violation"; violation: ProverViolation };

/** Starts the prover worker on this page's origin. */
export function startProver(opts: ProverOptions = {}): Prover {
  const origin = self.location.origin;
  const worker = new Worker(proverWorkerScriptURL() as string, { name: "prover" });
  const pending = new Map<number, { resolve: (v: unknown) => void; reject: (e: Error) => void }>();
  let next = 1;
  let dead: Error | null = null;
  const failAll = (e: Error) => {
    dead = e;
    for (const p of pending.values()) p.reject(e);
    pending.clear();
  };
  worker.addEventListener("message", (ev: MessageEvent<Reply>) => {
    const m = ev.data;
    if ("type" in m) {
      if (m.type === "violation") opts.onViolation?.(m.violation);
      return;
    }
    const p = pending.get(m.id);
    if (!p) return;
    pending.delete(m.id);
    if (m.ok) p.resolve(m.value);
    else p.reject(new Error(m.error));
  });
  worker.addEventListener("error", (ev: ErrorEvent) => failAll(new Error(`${PROVER_DEAD_PREFIX}${ev.message || "failed to load"}`)));
  // a reply the page cannot deserialize would leave its call waiting for ever; no timeout, as a slow phone's proof is not a hang
  worker.addEventListener("messageerror", () => failAll(new Error(`${PROVER_DEAD_PREFIX}a reply could not be read`)));
  const call = (msg: Record<string, unknown>, transfer: Transferable[] = []): Promise<unknown> =>
    new Promise((resolve, reject) => {
      if (dead) return reject(dead);
      const id = next++;
      pending.set(id, { resolve, reject });
      worker.postMessage({ ...msg, id }, transfer);
    });

  const fetchFile = async (name: "withdraw.wasm" | "withdraw.zkey" | "commitment.wasm" | "commitment.zkey"): Promise<ArrayBuffer> => {
    const r = await fetch(setupFileURL(name, origin), { credentials: "omit", cache: "no-cache" });
    if (!r.ok) throw new Error(`${name}: HTTP ${r.status}`);
    return r.arrayBuffer();
  };

  return {
    async load(circuit) {
      const [wasm, zkey] = await Promise.all([fetchFile(`${circuit}.wasm`), fetchFile(`${circuit}.zkey`)]);
      await call({ cmd: "load", circuit, wasm, zkey }, [wasm, zkey]);
    },
    async prove(circuit, input) {
      return (await call({ cmd: "prove", circuit, input })) as ProverResult;
    },
    terminate() {
      worker.terminate();
      failAll(new Error(`${PROVER_DEAD_PREFIX}terminated`));
    },
  };
}

packages/kit/src/vault/inputs.ts.body:
// A withdrawal's proof inputs, built on the device from the leaves it holds (card vault-input-builder; the vault paper
// V2.6, docs/plan1/vault.md l.1198, withdraw part). The proof is Privacy Pools v1.3.0's Withdraw(32)
// (packages/circuits/circuits/withdraw.circom:17-43 at c312dcd), run by the pinned withdraw.wasm (../zk/setup-files.ts).
//
// - The trees: the vault's state tree (every commitment) and label tree (every deposit's and refund note's label) are
//   LeanIMTs hashed with circomlib's Poseidon(2) (vault.md l.95-96). The device keeps one VaultTree for each, built
//   once with @zk-kit/lean-imt (the TS tree VT-P01 checks against the vault's Rust port, vault.md l.1126) and
//   poseidon-lite's poseidon2, and appends each new page of leaves as it reads them, so a path never rehashes the tree.
// - The roots: the kit proves against the vault's newest roots (vault.md l.145-146), which the caller reads on two
//   RPCs. A tree whose root is not that root is refused: a stale prefix of leaves would prove an old root the vault
//   still accepts and that dates the read, and a forged leaf would make a proof the vault refuses.
// - The path: LeanIMT's proof leaves out every level where the node has no sibling (that level's node equals its child),
//   and its index holds only the kept levels' left/right bits. The circuit's LeanIMTInclusionProof walks maxDepth = 32
//   levels, takes bit i of the index for level i and passes the node up unchanged where siblings[i] is 0
//   (merkleTree.circom l.58-75, the pass-up rule l.74, sha256 5754b7b0). So the kept siblings go first, in order, and 0s
//   fill the rest up to 32; the index is LeanIMT's, never the leaf's position. Any other padding or order gives another
//   root and fails at witness time.
// - The context is computed here from the withdrawal the user made (shapes.ts vaultContextOf), after every check the
//   vault would make of it (vaultWithdrawalProblems), so recipient and fee are bound to what the user typed.
// - Field rule: every value is a field element in [0, p) and is refused otherwise, never reduced (poseidon-lite reduces
//   silently). A leaf is also never 0 (vault.md l.246, 2.5.1 row 10). A repeated leaf blocks only the note it is.
// - No tree holds 2^32 leaves (a JS array's length is below 2^32), so no depth is over 32.
// Nothing here logs: the note's secrets never leave the device.
import { keccak_256 } from "@noble/hashes/sha3.js";
import { LeanIMT } from "@zk-kit/lean-imt";
import { poseidon2 } from "poseidon-lite/poseidon2";
import { poseidon3 } from "poseidon-lite/poseidon3";
import {
  VAULT_CONSTANTS,
  VAULT_FIELD_P,
  vaultContextInput,
  vaultContextOf,
  vaultWithdrawalProblems,
  type VaultWithdrawal,
} from "./shapes.ts";

const DEPTH = VAULT_CONSTANTS.MAX_TREE_DEPTH;
const U128 = 1n << 128n;

/** A path as the circuit reads it: the root it proves, the tree's depth, LeanIMT's index and 32 siblings. */
export type VaultMerklePath = { root: bigint; depth: number; index: number; siblings: bigint[] };

function field(x: bigint, what: string): bigint {
  if (typeof x !== "bigint" || x < 0n || x >= VAULT_FIELD_P) throw new Error(`${what}: not a field element in [0, p)`);
  return x;
}

const hash = (a: bigint, b: bigint): bigint => poseidon2([a, b]);

/** One of the vault's two trees on the device: built once, then grown by each page of leaves read from the vault. */
export class VaultTree {
  #tree = new LeanIMT<bigint>(hash);
  #first = new Map<bigint, number>();
  #repeated = new Set<bigint>();

  constructor(leaves: readonly bigint[] = []) {
    if (leaves.length > 0) this.append(leaves);
  }

  get size(): number {
    return this.#tree.size;
  }
  get depth(): number {
    return this.#tree.depth;
  }
  /** The root, or undefined while the tree is empty. */
  get root(): bigint | undefined {
    return this.#tree.size === 0 ? undefined : this.#tree.root;
  }

  /** Appends the vault's next leaves, in insert order. A page with a leaf not in [1, p) changes nothing. */
  append(page: readonly bigint[]): void {
    if (!Array.isArray(page) || page.length === 0) throw new Error("page: no leaves");
    for (const [i, leaf] of page.entries()) {
      field(leaf, `page[${i}]`);
      if (leaf === 0n) throw new Error(`page[${i}]: a leaf is never 0`);
    }
    const start = this.#tree.size;
    this.#tree.insertMany([...page]);
    for (const [i, leaf] of page.entries()) {
      if (this.#first.has(leaf)) this.#repeated.add(leaf);
      else this.#first.set(leaf, start + i);
    }
  }

  /** The circuit's path for `leaf`: LeanIMT's siblings then 0s up to 32, and LeanIMT's index. */
  path(leaf: bigint): VaultMerklePath {
    const at = this.#first.get(field(leaf, "leaf"));
    if (at === undefined) throw new Error("leaf: not in the tree");
    if (this.#repeated.has(leaf)) throw new Error("leaf: repeats in the tree");
    const p = this.#tree.generateProof(at);
    const siblings = [...p.siblings, ...Array<bigint>(DEPTH - p.siblings.length).fill(0n)];
    return { root: this.#tree.root, depth: this.#tree.depth, index: p.index, siblings };
  }
}

/** The root the circuit computes from a path (merkleTree.circom l.58-75), for checking a path on the device. */
export function vaultRootOfPath(leaf: bigint, index: number, siblings: readonly bigint[]): bigint {
  if (siblings.length !== DEPTH) throw new Error(`siblings: not ${DEPTH} of them`);
  if (!Number.isSafeInteger(index) || index < 0 || index >= 2 ** DEPTH) throw new Error("index: not below 2^32");
  let node = field(leaf, "leaf");
  for (let i = 0; i < DEPTH; i++) {
    const s = field(siblings[i]!, `siblings[${i}]`);
    if (s === 0n) continue;
    node = Math.floor(index / 2 ** i) % 2 === 1 ? hash(s, node) : hash(node, s);
  }
  return node;
}

/** Withdraw(32)'s `signal input`s, every value a decimal string, as snarkjs reads them. */
export type VaultWithdrawInput = {
  withdrawnValue: string;
  stateRoot: string;
  stateTreeDepth: string;
  ASPRoot: string;
  ASPTreeDepth: string;
  context: string;
  label: string;
  existingValue: string;
  existingNullifier: string;
  existingSecret: string;
  newNullifier: string;
  newSecret: string;
  stateSiblings: string[];
  stateIndex: string;
  ASPSiblings: string[];
  ASPIndex: string;
};

/** What the device knows when it spends a note. */
export type VaultWithdrawInputArgs = {
  /** The device's state tree and label tree, holding every leaf the vault has. */
  stateTree: VaultTree;
  labelTree: VaultTree;
  /** The vault's newest state root and label root, read on two RPCs. */
  newestStateRoot: bigint;
  newestLabelRoot: bigint;
  /** The note spent: its value and label from the vault, its secrets from the 12 words. */
  note: { value: bigint; label: bigint; nullifier: bigint; secret: bigint };
  /** The change note's secrets (value = note.value - withdrawn, same label). */
  newNullifier: bigint;
  newSecret: bigint;
  withdrawn: bigint;
  /** The withdrawal the user made, the vault's account id, its scope, and the time now in ms. */
  withdrawal: VaultWithdrawal;
  vaultId: string;
  scope: bigint;
  nowMs: number;
};

/**
 * Withdraw(32)'s inputs to spend `note`, withdrawing `withdrawn` and leaving the rest as a change note under the same
 * label. Refuses what the circuit or the vault would refuse, before the device spends a proof on it: a withdrawal
 * vaultWithdrawalProblems names, a tree whose root is not the vault's newest, a note whose commitment is not in the
 * state tree or whose label is not in the label tree (or repeats there), withdrawn over the note's value, a value of
 * 2^128 or more, the change nullifier equal to the spent one, and any value not below p.
 */
export function vaultWithdrawInput(a: VaultWithdrawInputArgs): VaultWithdrawInput {
  const scope = field(a.scope, "scope");
  const { withdrawal, vaultId, nowMs, scope: _scope, ...rest } = a;
  const problems = vaultWithdrawalProblems(withdrawal, field(a.withdrawn, "withdrawn"), vaultId, nowMs);
  if (problems.length > 0) throw new Error(`withdrawal: ${problems.join("; ")}`);
  return poolWithdrawInput({ ...rest, context: vaultContextOf(keccak_256, vaultContextInput(vaultId, withdrawal), scope) });
}

/**
 * What the device knows when it spends a note in any pool on this circuit (the NEAR vault, the Solana and EVM pools):
 * the same as VaultWithdrawInputArgs, with the context the pool's own context function computed in place of the
 * vault's withdrawal, account id, scope and time. The pool checks its own request fields before it gives the context.
 */
export type PoolWithdrawInputArgs = Omit<VaultWithdrawInputArgs, "withdrawal" | "vaultId" | "scope" | "nowMs"> & { context: bigint };

/**
 * Withdraw(32)'s inputs for a spend in any pool, against the pool's newest roots, with the pool's context as the 8th
 * public signal. Refuses what vaultWithdrawInput refuses, the vault's withdrawal checks aside but withdrawn 0, and a
 * context not below p.
 */
export function poolWithdrawInput(a: PoolWithdrawInputArgs): VaultWithdrawInput {
  const value = field(a.note.value, "note.value");
  const label = field(a.note.label, "note.label");
  const nullifier = field(a.note.nullifier, "note.nullifier");
  const secret = field(a.note.secret, "note.secret");
  const newNullifier = field(a.newNullifier, "newNullifier");
  const newSecret = field(a.newSecret, "newSecret");
  const withdrawn = field(a.withdrawn, "withdrawn");
  const context = field(a.context, "context");
  if (value >= U128) throw new Error("note.value: 2^128 or more");
  if (withdrawn === 0n) throw new Error("withdrawn: 0"); // the vault refuses it (vaultWithdrawalProblems)
  if (withdrawn > value) throw new Error("withdrawn: over the note's value");
  if (newNullifier === nullifier) throw new Error("newNullifier: equals the spent note's nullifier");

  if (a.stateTree.root !== field(a.newestStateRoot, "newestStateRoot")) throw new Error("stateTree: its root is not the vault's newest");
  if (a.labelTree.root !== field(a.newestLabelRoot, "newestLabelRoot")) throw new Error("labelTree: its root is not the vault's newest");
  // commitment.circom:24-36: commitment = Poseidon(value, label, Poseidon(nullifier, secret))
  const commitment = poseidon3([value, label, poseidon2([nullifier, secret])]);
  const s = pathOf(a.stateTree, commitment, "the note's commitment");
  const l = pathOf(a.labelTree, label, "the note's label");

  return {
    withdrawnValue: String(withdrawn),
    stateRoot: String(s.root),
    stateTreeDepth: String(s.depth),
    ASPRoot: String(l.root),
    ASPTreeDepth: String(l.depth),
    context: String(context),
    label: String(label),
    existingValue: String(value),
    existingNullifier: String(nullifier),
    existingSecret: String(secret),
    newNullifier: String(newNullifier),
    newSecret: String(newSecret),
    stateSiblings: s.siblings.map(String),
    stateIndex: String(s.index),
    ASPSiblings: l.siblings.map(String),
    ASPIndex: String(l.index),
  };
}

function pathOf(t: VaultTree, leaf: bigint, what: string): VaultMerklePath {
  try {
    return t.path(leaf);
  } catch (e) {
    throw new Error(`${what}: ${e instanceof Error ? e.message : String(e)}`);
  }
}

packages/kit/src/vault/sync.ts.body:
// The vault's pages, read on two RPCs and matched on the device (card vault-kit-sync; the vault paper V4.1, 2.5.6 and
// 2.10 (c), docs/plan1/vault.md l.1230, l.492-501, l.674-676). Every list the vault pages (deposits, spends, leaves,
// labels) and both trees' heads, read from a cursor so a caller resumes where it stopped instead of from 0.
//
// - One block on both RPCs. Each RPC's final height is read first (state_tree at final); every read after it names
//   the lower of the two by block_id, so two honest RPCs answer the same state and any difference is a lie or a fault,
//   never lag. An RPC ahead of the other only waits: its newer rows come in the next sync. Both answers must carry
//   that height and the same block hash. Final heights more than VAULT_SYNC_LAG_MAX (the device's window W) apart
//   stop the sync ("lag"): one RPC is stuck or lying, and a read at its height would be stale. A caller that needs a
//   block at or above a height (a signed call's max_block_height + 5) puts it in cursor.height ("behind" below it).
// - Byte for byte. Each view's answer bytes must be equal on both RPCs (vault paper 2.12 step 2), else the sync stops
//   (VaultSyncStopped "disagree"): an extra, missing or changed row on one RPC, a tree head that differs, another
//   block. One RPC down, or an answer that is not a view result, stops it too ("rpc"). Nothing is returned from a
//   stopped sync and the caller's cursor is never changed, so a stop costs a read again, never a row.
// - Rows as the vault writes them. Every row is checked as contracts/vault/src/lib.rs's views write it: its exact
//   fields, in its order, once each, compact, so the answer must be the bytes the vault's serializer writes for
//   the rows parsed from it; its index at its place, decimals canonical and below p, amounts u128, account ids NEAR
//   ids ("row").
// - The cursor moves only past rows both RPCs gave. A reported count never moves it: the leaves and labels read must
//   end at their tree's size, which both RPCs gave equal ("count" otherwise, and for a cursor past that size), and the
//   deposits and spends cursors move by the rows read; a deposits or spends cursor c > 0 that reads no row must find
//   row c - 1 ("count" otherwise), so a cursor past the list's end never skips the rows written later. Every list is
//   append-only (2.5.6), so the rows below a cursor never change, with one exception: a spend's status and refund
//   fields change until it is settled (2.5.5), so the spends cursor stops at the first spend not settled and the next
//   sync reads it again (a row read again replaces the earlier copy, by its index).
// - No lookup of one secret-derived value: whole pages only, matched here (2.5.6). Deposits are confirmed from these
//   rows, never from a transaction read by hash (2.10 (c)).
// - An abort ends the sync at once, even inside a read an RPC never answers; the signal goes to the RPC's query too.
// The kit names no provider: the caller passes two RPCs of different operators (the wallet's NEAR_NETWORKS pair).
import { VAULT_CONSTANTS, VAULT_FIELD_P, vaultAccountId, vaultDecimal, type VaultSpendStatus } from "./shapes.ts";

/**
 * A NEAR JSON-RPC provider's `query` method: the params of one query, its whole JSON-RPC answer. The signal is the
 * sync's; a provider may end its request on it (the sync stops waiting on its own either way).
 */
export interface VaultSyncRpc {
  name: string;
  query(params: Record<string, unknown>, signal?: AbortSignal): Promise<unknown>;
}

/**
 * The most the two RPCs' final heights may differ, in blocks: the device's window W, 120 blocks or about 70 s (vault
 * paper 2.10 (b), docs/plan1/vault.md l.670-672). Two honest RPCs differ by a block or two.
 */
export const VAULT_SYNC_LAG_MAX = 120;

/** The lists the vault pages (2.5.6). */
export const VAULT_SYNC_LISTS = ["deposits", "spends", "leaves", "labels"] as const;
export type VaultSyncList = (typeof VAULT_SYNC_LISTS)[number];

/**
 * Where the next sync starts: per list, the first row it reads; the height the last sync read at, which the next must
 * not be below. JSON numbers only, so a caller stores it as is.
 */
export type VaultSyncCursor = { vault: string; height: number } & Record<VaultSyncList, number>;

/** The cursor of a vault never read: every list from 0. */
export function vaultSyncStart(vault: string): VaultSyncCursor {
  return { vault: vaultAccountId(vault, "vault"), height: 0, deposits: 0, spends: 0, leaves: 0, labels: 0 };
}

/** A row of the deposits view (DepositView). */
export type VaultDepositRow = { index: number; precommitment: bigint; label: bigint; value: bigint; leafIndex: bigint; depositor: string };
/** A row of the spends view (SpendView): the spend, its request data and its refund note's fields. */
export type VaultSpendRow = {
  index: number;
  nullifierHash: bigint;
  withdrawn: bigint;
  newLeafIndex: bigint;
  refundPrecommitment: bigint;
  refundValue: bigint;
  refundLabel: bigint;
  refundLeafIndex: bigint;
  status: VaultSpendStatus;
  payer: string;
  reserve: bigint;
  recipient: string;
  fee: bigint;
  context: bigint;
};
/** state_tree() or label_tree(). */
export type VaultTreeHead = { size: number; depth: number; root: bigint };

export type VaultSyncResult = {
  /** The block every read named, on both RPCs. */
  height: number;
  blockHash: string;
  stateTree: VaultTreeHead;
  labelTree: VaultTreeHead;
  /** Each list's rows from the cursor given to its end at `height`; a list not asked for is empty. */
  deposits: VaultDepositRow[];
  spends: VaultSpendRow[];
  /** Leaves and labels from the cursor's leaves and labels index on. */
  leaves: bigint[];
  labels: bigint[];
  /** The next sync's start. */
  cursor: VaultSyncCursor;
};

export type VaultSyncStopCode = "input" | "rpc" | "disagree" | "row" | "count" | "behind" | "lag";
export class VaultSyncStopped extends Error {
  readonly code: VaultSyncStopCode;
  constructor(code: VaultSyncStopCode, detail: string) {
    super(`vault sync stopped (${code}): ${detail}`);
    this.name = "VaultSyncStopped";
    this.code = code;
  }
}

export type VaultSyncArgs = {
  vault: string;
  /** Two RPCs of different operators. */
  rpcs: readonly [VaultSyncRpc, VaultSyncRpc];
  /** vaultSyncStart(vault) on a first read; else the cursor the last sync returned. */
  cursor: VaultSyncCursor;
  /** The lists to read; all four unless given. Lists not read keep their cursor. */
  lists?: readonly VaultSyncList[];
  signal?: AbortSignal;
};

/** Reads the vault's pages from `cursor` on both RPCs at one block and returns the rows both gave, byte for byte. */
export async function vaultSync(args: VaultSyncArgs): Promise<VaultSyncResult> {
  const { vault, rpcs, cursor, signal } = args;
  const lists = args.lists ?? VAULT_SYNC_LISTS;
  checkInput(vault, rpcs, cursor, lists);

  // The two final heights; every read after this one names the lower.
  signal?.throwIfAborted();
  const probe = call(vault, "state_tree", {}, { finality: "final" });
  const finals = await Promise.all([answer(rpcs[0], probe, signal), answer(rpcs[1], probe, signal)]);
  if (Math.abs(finals[0].height - finals[1].height) > VAULT_SYNC_LAG_MAX)
    throw new VaultSyncStopped("lag", `the RPCs' final heights ${finals[0].height} and ${finals[1].height} are over ${VAULT_SYNC_LAG_MAX} blocks apart`);
  const height = Math.min(finals[0].height, finals[1].height);
  if (height < cursor.height) throw new VaultSyncStopped("behind", `the RPCs' final height ${height} is below the cursor's ${cursor.height}`);

  let blockHash = "";
  const read = async (method: string, a: Record<string, number>): Promise<unknown> => {
    signal?.throwIfAborted();
    const at = call(vault, method, a, { block_id: height });
    const [x, y] = await Promise.all([answer(rpcs[0], at, signal), answer(rpcs[1], at, signal)]);
    if (x.height !== height || y.height !== height) throw new VaultSyncStopped("rpc", `${method}: an answer not at block ${height}`);
    if (x.hash !== y.hash || (blockHash !== "" && x.hash !== blockHash)) throw new VaultSyncStopped("disagree", `${method}: two blocks at height ${height}`);
    blockHash = x.hash;
    if (!sameBytes(x.bytes, y.bytes)) throw new VaultSyncStopped("disagree", `${method}(${JSON.stringify(a)}): the RPCs' answers differ`);
    let text: string;
    try {
      text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(x.bytes);
    } catch {
      throw new VaultSyncStopped("row", `${method}: not UTF-8`);
    }
    let value: unknown;
    try {
      value = JSON.parse(text);
    } catch {
      throw new VaultSyncStopped("row", `${method}: not JSON`);
    }
    if (JSON.stringify(inVaultOrder(method, value)) !== text)
      throw new VaultSyncStopped("row", `${method}: not the vault's own bytes (field order, a repeated field, spacing or a number's form)`);
    return value;
  };

  const stateTree = head(await read("state_tree", {}), "state_tree");
  const labelTree = head(await read("label_tree", {}), "label_tree");
  const next: VaultSyncCursor = { ...cursor, height };
  const out: VaultSyncResult = { height, blockHash, stateTree, labelTree, deposits: [], spends: [], leaves: [], labels: [], cursor: next };

  for (const list of VAULT_SYNC_LISTS) {
    if (!lists.includes(list)) continue;
    const from = cursor[list];
    const size = list === "leaves" ? stateTree.size : list === "labels" ? labelTree.size : null;
    const rows: unknown[] = [];
    for (let at = from; ; at += VAULT_CONSTANTS.PAGE_MAX) {
      const page = await read(list, { from: at, limit: VAULT_CONSTANTS.PAGE_MAX });
      if (!Array.isArray(page) || page.length > VAULT_CONSTANTS.PAGE_MAX) throw new VaultSyncStopped("row", `${list}: not a page`);
      page.forEach((x, k) => rows.push(parseRow(list, x, at + k)));
      if (page.length < VAULT_CONSTANTS.PAGE_MAX) break;
    }
    // A deposits or spends cursor past the list's end would read no row and wait there, skipping every row written
    // below it later: an empty read from c > 0 must find row c - 1.
    if (size === null && rows.length === 0 && from > 0) {
      const last = await read(list, { from: from - 1, limit: 1 });
      if (!Array.isArray(last) || last.length !== 1) throw new VaultSyncStopped("count", `${list}: the cursor ${from} is past the list's end`);
      parseRow(list, last[0], from - 1);
    }
    const end = from + rows.length; // a cursor past the list's end reads no row, so it ends past the tree's size too
    if (size !== null && end !== size) throw new VaultSyncStopped("count", `${list}: the pages end at ${end}, the tree's size is ${size}`);
    if (list === "deposits") out.deposits = rows as VaultDepositRow[];
    else if (list === "spends") out.spends = rows as VaultSpendRow[];
    else out[list] = rows as bigint[];
    // A spend can change until it is settled: the next sync starts at the first one that is not.
    const open = list === "spends" ? out.spends.findIndex((s) => s.status !== "settled") : -1;
    next[list] = open === -1 ? end : from + open;
  }
  return out;
}

// ---------- reads ----------
type Obj = Record<string, unknown>;
const isObj = (x: unknown): x is Obj => typeof x === "object" && x !== null && !Array.isArray(x);

function call(vault: string, method: string, a: Record<string, number>, at: { finality: "final" } | { block_id: number }): Obj {
  return { request_type: "call_function", account_id: vault, method_name: method, args_base64: btoa(JSON.stringify(a)), ...at };
}

/** One RPC's answer to one view call: its bytes, height and block hash, or a stop ("rpc"). */
async function answer(rpc: VaultSyncRpc, params: Obj, signal?: AbortSignal): Promise<{ bytes: Uint8Array; height: number; hash: string }> {
  let a: unknown;
  try {
    a = await untilAbort(rpc.query(params, signal), signal);
  } catch (e) {
    if (signal?.aborted) throw signal.reason;
    throw new VaultSyncStopped("rpc", `${rpc.name}: ${e instanceof Error ? e.message : String(e)}`);
  }
  const r = isObj(a) && a.error === undefined ? a.result : undefined;
  const bytes = isObj(r) && r.error === undefined ? r.result : undefined;
  if (
    !isObj(r) ||
    !Number.isSafeInteger(r.block_height) ||
    (r.block_height as number) <= 0 ||
    typeof r.block_hash !== "string" ||
    !Array.isArray(bytes) ||
    !bytes.every((b) => Number.isInteger(b) && b >= 0 && b <= 255)
  )
    throw new VaultSyncStopped("rpc", `${rpc.name}: ${String(params.method_name)}: not a view result`);
  return { bytes: Uint8Array.from(bytes as number[]), height: r.block_height as number, hash: r.block_hash };
}

/** p, or the signal's reason once it aborts, whichever comes first. */
function untilAbort<T>(p: Promise<T>, signal?: AbortSignal): Promise<T> {
  if (!signal) return p;
  return new Promise<T>((resolve, reject) => {
    const stop = () => reject(signal.reason);
    if (signal.aborted) return stop();
    signal.addEventListener("abort", stop, { once: true });
    p.then(resolve, reject).finally(() => signal.removeEventListener("abort", stop));
  });
}

function sameBytes(a: Uint8Array, b: Uint8Array): boolean {
  return a.length === b.length && a.every((v, i) => v === b[i]);
}

function checkInput(vault: string, rpcs: readonly [VaultSyncRpc, VaultSyncRpc], cursor: VaultSyncCursor, lists: readonly VaultSyncList[]): void {
  const no = (d: string) => new VaultSyncStopped("input", d);
  try {
    vaultAccountId(vault, "vault");
  } catch (e) {
    throw no((e as Error).message);
  }
  if (!Array.isArray(rpcs) || rpcs.length !== 2 || !rpcs.every((r) => isObj(r) && typeof r.query === "function" && typeof r.name === "string"))
    throw no("two RPCs, each with a name and query");
  if (rpcs[0] === rpcs[1] || rpcs[0].name === rpcs[1].name) throw no("the two RPCs are one");
  if (!isObj(cursor) || cursor.vault !== vault) throw no("the cursor is not this vault's");
  for (const k of ["height", ...VAULT_SYNC_LISTS] as const) if (!Number.isSafeInteger(cursor[k]) || cursor[k] < 0) throw no(`cursor.${k}: not a whole number`);
  if (!Array.isArray(lists) || !lists.every((l) => (VAULT_SYNC_LISTS as readonly string[]).includes(l))) throw no(`lists: only ${VAULT_SYNC_LISTS.join(", ")}`);
}

// ---------- rows, as the vault's views write them (contracts/vault/src/lib.rs) ----------
const DEPOSIT_FIELDS = ["index", "precommitment", "label", "value", "leaf_index", "depositor"];
const SPEND_FIELDS = [
  "index",
  "nullifier_hash",
  "withdrawn",
  "new_leaf_index",
  "refund_precommitment",
  "refund_value",
  "refund_label",
  "refund_leaf_index",
  "status",
  "payer",
  "reserve",
  "recipient",
  "fee",
  "context",
];
const TREE_FIELDS = ["size", "depth", "root"];
const STATUSES: readonly VaultSpendStatus[] = ["in_flight", "paid", "refund_pending", "settled"];

/** A view's value with each object's fields in the vault's struct order, as its serializer writes them. */
function inVaultOrder(method: string, v: unknown): unknown {
  const order = method === "deposits" ? DEPOSIT_FIELDS : method === "spends" ? SPEND_FIELDS : method.endsWith("_tree") ? TREE_FIELDS : null;
  if (order === null) return v;
  const pick = (o: unknown) => (isObj(o) ? Object.fromEntries(order.map((k) => [k, o[k]])) : o);
  return Array.isArray(v) ? v.map(pick) : pick(v);
}

function parseRow(list: VaultSyncList, x: unknown, at: number): unknown {
  try {
    if (list === "leaves" || list === "labels") return field(x, "leaf");
    const o = fields(x, list === "deposits" ? DEPOSIT_FIELDS : SPEND_FIELDS);
    if (o.index !== at) throw new Error(`index ${String(o.index)} at ${at}`);
    if (list === "deposits")
      return {
        index: at,
        precommitment: field(o.precommitment, "precommitment"),
        label: field(o.label, "label"),
        value: u128(o.value, "value"),
        leafIndex: u64(o.leaf_index, "leaf_index"),
        depositor: vaultAccountId(o.depositor as string, "depositor"),
      } satisfies VaultDepositRow;
    if (!STATUSES.includes(o.status as VaultSpendStatus)) throw new Error("status: not a spend status");
    return {
      index: at,
      nullifierHash: field(o.nullifier_hash, "nullifier_hash"),
      withdrawn: u128(o.withdrawn, "withdrawn"),
      newLeafIndex: u64(o.new_leaf_index, "new_leaf_index"),
      refundPrecommitment: field(o.refund_precommitment, "refund_precommitment"),
      refundValue: u128(o.refund_value, "refund_value"),
      refundLabel: field(o.refund_label, "refund_label"),
      refundLeafIndex: u64(o.refund_leaf_index, "refund_leaf_index"),
      status: o.status as VaultSpendStatus,
      payer: vaultAccountId(o.payer as string, "payer"),
      reserve: u128(o.reserve, "reserve"),
      recipient: vaultAccountId(o.recipient as string, "recipient"),
      fee: u128(o.fee, "fee"),
      context: field(o.context, "context"),
    } satisfies VaultSpendRow;
  } catch (e) {
    throw new VaultSyncStopped("row", `${list} row ${at}: ${(e as Error).message}`);
  }
}

function head(x: unknown, what: string): VaultTreeHead {
  try {
    const o = fields(x, TREE_FIELDS);
    const depth = o.depth;
    if (!Number.isSafeInteger(depth) || (depth as number) < 0 || (depth as number) > VAULT_CONSTANTS.MAX_TREE_DEPTH) throw new Error("depth");
    return { size: Number(u64(o.size, "size")), depth: depth as number, root: field(o.root, "root") };
  } catch (e) {
    throw new VaultSyncStopped("row", `${what}: ${(e as Error).message}`);
  }
}

/** An object with every one of these fields (an extra, repeated or reordered field is refused before, by the bytes check in read). */
function fields(x: unknown, names: readonly string[]): Obj {
  if (!isObj(x)) throw new Error("not an object");
  const keys = Object.keys(x);
  if (!names.every((n) => keys.includes(n))) throw new Error(`fields: not ${names.join(", ")}`);
  return x;
}
function field(x: unknown, what: string): bigint {
  const n = vaultDecimal(x as string, what);
  if (n >= VAULT_FIELD_P) throw new Error(`${what}: not below p`);
  return n;
}
function u128(x: unknown, what: string): bigint {
  const n = vaultDecimal(x as string, what);
  if (n >= 1n << 128n) throw new Error(`${what}: not a u128`);
  return n;
}
/** A u64 the vault writes as a JSON number: a safe integer here, since every index is below 2^53. */
function u64(x: unknown, what: string): bigint {
  if (!Number.isSafeInteger(x) || (x as number) < 0) throw new Error(`${what}: not a whole number`);
  return BigInt(x as number);
}

packages/kit/src/trade/solana/send.ts.body:
// The Solana set send (markets paper T2.1 "Sending" and LD2, docs/plan1/markets.md l.93 and l.336-346; row M1.3).
// Device side. It carries only bytes the device already signed: it holds no key, builds no transaction and changes no
// byte. Signed bytes cannot be altered by whoever carries them and the first copy to land wins, so every path gets
// the same bytes and no single path can hold a trade back (LD2).
//
// - Send: in the first tick, before sendSolanaSet returns, every tx goes to every RPC path that its URL's queue lets
//   start now (a public RPC, and the helper's `/v1/rpc/solana` `sendTransaction` when the app has a helper; see the
//   provider queue below: 40 a method in any 10 s keyless, so a set of 40 all goes at once),
//   and one tx to each 1-request-a-second path whose URL has had no request in the last second (keyless Helius Sender
//   `/fast?swqos_only=true` gets the set's first tx, the Jito block engine `/api/v1/transactions` its second; both
//   limits count refused requests too). A path that is down, refusing or slow is recorded and holds nothing back.
// - Rebroadcast: every SOLANA_REBROADCAST_MS (2 s, the paper's DESIGN interval from P4S) on the unlimited paths; on
//   each 1-rps URL one request a second, shared by every set in flight on this page (one pacer per URL), each set
//   rotating through its undecided txs. A tx is never sent again once it is decided, or
//   once both providers' finalized height is past its lastValidBlockHeight and both read its blockhash as no longer
//   valid at `processed` (06c §3.4).
// - Fill: read on two providers (the same [A, B] pair the quote checks read, checks/solana/checks.ts SolanaQuoteReads;
//   §2.0 LD1: at least one device-direct, the second may be the helper's /v1/rpc), never the same one twice. A tx is
//   filled only when both have read it at `confirmed` or `finalized` with no error, failed only when both read it
//   landed with an error. Dead (expired) follows 06c A4 (06c-chain-adapters.md l.98), on each provider: its finalized
//   height past lastValidBlockHeight, its blockhash read valid and then, from a bank at or above that one, no longer
//   valid at `processed` (so a lowered lastValidBlockHeight from whoever built the tx cannot make a live tx look dead;
//   valid first, because Agave answers false alike for an expired hash and for one its bank does not hold yet,
//   accounts-db blockhash_queue.rs:98-108 at v4.3.2), and then a status read with searchTransactionHistory: true
//   (so a landing older than the status cache's 300 roots is still found) that has no signature, taken from a bank at
//   or past the slot the height and the blockhash check were read at (so a node behind a load balancer that has not
//   replayed the landing block cannot answer it). Anything else, one provider's word included, decides nothing; at
//   the deadline it stays "unknown", which the caller must re-read before it moves money on, never a fill and never
//   dead.
//
// Every answer from a path or a provider is hostile input: it is size-bounded, shape-checked, and an answer that fails
// a check counts as no answer. A provider answering 429 is backed off, up to 8 s; a 429 is no answer.
import { base58, base64 } from "@scure/base";
import { HELPER_FETCH_INIT, HELPER_V1_PREFIX } from "../../helper/v1.ts";
import { SOLANA_MAX_TX_BYTES, solanaDecodeTransaction } from "../../checks/solana/message.ts";
import { SOLANA_SYSTEM_PROGRAM } from "../../checks/solana/checks.ts";

// Helius Sender, the global HTTPS endpoint with the SWQoS-only route: https://www.helius.dev/docs/sending-transactions/sender.md
// ("https://sender.helius-rpc.com/fast # Global HTTPS endpoint", which "resolves CORS preflight failures ... with
// browser-based applications"; "Add `?swqos_only=true` to any endpoint URL"; keyless "limited to 1 request per second").
// Its preflight answered Access-Control-Allow-Origin: * between 2026-11-02 01:54Z and 01:57Z (date -u before and after the read).
export const SOLANA_SENDER_FAST_URL = "https://sender.helius-rpc.com/fast?swqos_only=true";
// The Jito block engine's sendTransaction: https://docs.jito.wtf/lowlatencytxnsend/ ("this method always sets
// skip_preflight=true"; its examples send params [tx, { encoding }] only). Its preflight from the app's origin answered
// that origin between 2026-11-02 01:54Z and 01:57Z (date -u before and after the read).
export const SOLANA_JITO_TRANSACTIONS_URL = "https://mainnet.block-engine.jito.wtf/api/v1/transactions";
// The public mainnet RPC: https://solana.com/docs/references/clusters (100 requests per 10 s per IP). Its preflight
// from the app's origin answered that origin between 2026-11-02 01:54Z and 01:57Z (date -u before and after the read).
export const SOLANA_PUBLIC_RPC_URL = "https://api.mainnet-beta.solana.com";

/** The paper's rebroadcast interval (T2.1, DESIGN from P4S). */
export const SOLANA_REBROADCAST_MS = 2_000;
/** Keyless Helius Sender and the Jito block engine each take 1 request a second per IP, refused ones included
 * (helius.dev/docs/sending-transactions/sender.md "Keyless requests are limited to 1 request per second";
 * docs.jito.wtf/lowlatencytxnsend "1 request per second per IP per region"). */
export const SOLANA_KEYLESS_PATH_INTERVAL_MS = 1_000;
/** How often the fill is read on each provider: about two slots (mainnet slots ran about 212 ms on 2026-11-02, the
 * reviewer's getRecentPerformanceSamples read). A read still open when the next is due is not stacked. */
export const SOLANA_STATUS_POLL_MS = 400;
/** One path call or provider read is given up after this. */
export const SOLANA_CALL_TIMEOUT_MS = 5_000;
/** The set is given up after this, its undecided txs "unknown". A blockhash lives 150 blocks, about 32 s at 212 ms
 * slots, and a finalized height trails the tip by about 32 slots, so a tx with no verdict by then needs a fresh read. */
export const SOLANA_SET_DEADLINE_MS = 120_000;
/** An answer larger than this is refused unread. A status or send answer is well under 64 KiB for a set of 256. */
export const SOLANA_ANSWER_MAX_BYTES = 1024 * 1024;
/** Agave answers getLatestBlockhash with lastValidBlockHeight = the bank's block height + MAX_PROCESSING_AGE (150)
 * for the bank's own latest blockhash, so the finalized bank's height is that minus 150, from the same bank as its
 * context.slot. */
const MAX_PROCESSING_AGE = 150;
/** A provider answering 429 waits 1 s, then twice as long each time, up to this. */
const BACKOFF_MAX_MS = 8_000;
/** A provider's limit: at most `total` calls, and at most `perMethod` calls of one method, starting in any `windowMs`. */
export type SolanaRpcLimit = { readonly windowMs: number; readonly total: number; readonly perMethod: number };
/** A keyless provider's limit: Solana's public RPC allows 100 requests per 10 s per IP, and 40 per 10 s for one method
 * (solana.com/docs/references/clusters.md, read 2026-10-25); PublicNode publishes no number and is held to the same. */
export const SOLANA_KEYLESS_RPC_LIMIT: SolanaRpcLimit = { windowMs: 10_000, total: 100, perMethod: 40 };
/** A keyed provider named by its requests a second: that many in any second, of all methods. */
export const solanaRpsLimit = (rps: number): SolanaRpcLimit => ({ windowMs: 1_000, total: rps, perMethod: rps });

// One queue per provider, shared by every call the kit makes on it: a trade's reads, simulations, re-reads, fill reads,
// settle reads and every teardown's, the sends on an RPC path, and any other set or trade in flight on the same
// provider. Keyed on the provider's URL (the limit is the provider's, per caller IP), or on its own function when it has
// none, so a provider wrapped by solanaPacedRpc and the same provider passed bare share one queue. Every limit named for
// the provider is kept and each call fits all of them, so the strictest holds whoever names it. Calls of one method start
// in the order they asked (first in, first out, so no caller starves another), each at the first time the limits allow:
// a method whose budget is spent waits alone, and the others go on, the total still counted over all methods.
// Each call is a slot: reserved at the first time the limits allow after the slot of its method before it, then checked
// again when its time comes against the calls that really started, and started then or later (a busy page starts a
// timer late, and the limits hold on the times the calls went out).
type RpcSlot = { t: number; method: string; started: boolean };
// fillSteady: when each steady fill read (past its set's burst, fillPool) went out on the provider, by every set on it.
type RpcQueue = { lastOf: Map<string, number>; slots: RpcSlot[]; limits: Map<string, SolanaRpcLimit>; fillSteady: number[] };
const queueOfUrl = new Map<string, RpcQueue>();
const queueOfFn = new WeakMap<SolanaRpc, RpcQueue>();
const bareOf = new WeakMap<SolanaRpc, SolanaRpc>();
const WINDOW_MAX_MS = 60_000;
// The queue's clock: monotonic, so a step of the wall clock (an NTP fix, a user changing the time) can never make the
// calls in a window look older than they are and let one more through.
const queueNow = (): number => performance.now();
// A URL as one key whatever its spelling (a trailing slash, the case of the host), so one provider is one queue.
const urlKeys = new Map<string, string>();
function urlKey(u: string): string {
  let k = urlKeys.get(u);
  if (k === undefined) {
    try { k = new URL(u).href; } catch { k = u; }
    if (urlKeys.size < 10_000) urlKeys.set(u, k);
  }
  return k;
}
/** The first time at or after `from` that a call of `method` fits every limit beside `slots`. Times are whole ms, so a
 * window is held 1 ms longer: a call at 0.9 ms and one at 1000.0 ms are in one second on a finer clock. */
function fitsAt(slots: readonly RpcSlot[], limits: Iterable<SolanaRpcLimit>, method: string, from: number): number {
  let t = from;
  const all = slots.map((x) => x.t).sort((x, y) => x - y);
  const same = slots.filter((x) => x.method === method).map((x) => x.t).sort((x, y) => x - y);
  for (const limit of limits) {
    if (all.length >= limit.total) t = Math.max(t, all[all.length - limit.total]! + limit.windowMs + 1);
    if (same.length >= limit.perMethod) t = Math.max(t, same[same.length - limit.perMethod]! + limit.windowMs + 1);
  }
  return t;
}
/** The provider's queue, with this limit named in it: named as soon as a caller holds the provider under it (a paced
 * wrapper made, a set or trade started), so the strictest limit binds every caller's calls from then, before its own. */
function queueWith(rpc: SolanaRpc, limit: SolanaRpcLimit): RpcQueue {
  if (![limit?.windowMs, limit?.total, limit?.perMethod].every((x) => typeof x === "number" && Number.isSafeInteger(x) && x > 0) || limit.windowMs > WINDOW_MAX_MS) throw new Error("a provider's limit must be whole numbers above 0, its window at most 60 s");
  const bare = bareOf.get(rpc) ?? rpc;
  let q = bare.url === undefined ? queueOfFn.get(bare) : queueOfUrl.get(urlKey(bare.url));
  if (!q) {
    q = { lastOf: new Map(), slots: [], limits: new Map(), fillSteady: [] };
    if (bare.url === undefined) queueOfFn.set(bare, q);
    else queueOfUrl.set(urlKey(bare.url), q);
  }
  q.limits.set(`${limit.windowMs}/${limit.total}/${limit.perMethod}`, { windowMs: limit.windowMs, total: limit.total, perMethod: limit.perMethod });
  return q;
}
function rpcSlot(rpc: SolanaRpc, limit: SolanaRpcLimit, method: string): { run: (params: readonly unknown[]) => Promise<unknown>; wait: Promise<void> | null; drop: () => void } {
  const queue = queueWith(rpc, limit);
  const bare = bareOf.get(rpc) ?? rpc;
  const now = queueNow();
  queue.slots = queue.slots.filter((x) => !x.started || x.t > now - WINDOW_MAX_MS);
  const slot: RpcSlot = { t: fitsAt(queue.slots, queue.limits.values(), method, Math.max(now, queue.lastOf.get(method) ?? 0)), method, started: false };
  queue.lastOf.set(method, slot.t);
  queue.slots.push(slot);
  // How long until the calls that really went out leave room for this one (0: now).
  const room = (): number => {
    const at = queueNow();
    return fitsAt(queue.slots.filter((x) => x.started), queue.limits.values(), method, at) - at;
  };
  // The call itself: checked against the calls that went out, then marked started and sent in the same tick, so no
  // other call is let through on a start time this one has not kept (a caller that runs it late waits again).
  const run = (params: readonly unknown[]): Promise<unknown> => {
    const ms = room();
    if (ms > 0) return new Promise<void>((r) => setTimeout(r, ms)).then(() => run(params));
    slot.t = queueNow();
    slot.started = true;
    // Stamped again once the call has been handed over: a pause in between (a GC, a slow tick) then makes the call look
    // later, never earlier, than when it left this queue, so the window this queue counts never starts too soon.
    try {
      return bare(method, params);
    } finally {
      slot.t = queueNow();
    }
  };
  // A turn its caller gives up on before the call starts (the set is over; never a started one): taken out of the
  // queue, so it holds back no later call and the queue keeps no slot for it.
  const drop = (): void => {
    queue.slots = queue.slots.filter((x) => x !== slot);
    const last = queue.slots.filter((x) => x.method === method).reduce((m, x) => Math.max(m, x.t), -Infinity);
    if (last === -Infinity) queue.lastOf.delete(method);
    else queue.lastOf.set(method, last);
  };
  if (slot.t <= now && room() <= 0) return { run, wait: null, drop };
  return {
    run,
    drop,
    wait: new Promise<void>((resolve) => {
      const go = () => { const ms = room(); if (ms <= 0) resolve(); else setTimeout(go, ms); };
      setTimeout(go, Math.max(0, slot.t - now));
    }),
  };
}
/** How long a call of `method` on the provider would wait if asked now (0: it starts at once, behind no call of the
 * method that waits there); it asks nothing and books nothing. */
function methodWaitMs(rpc: SolanaRpc, limit: SolanaRpcLimit, method: string): number {
  const queue = queueWith(rpc, limit);
  const now = queueNow();
  return Math.max(0, fitsAt(queue.slots, queue.limits.values(), method, Math.max(now, queue.lastOf.get(method) ?? 0)) - now);
}
// The fill poll's share of a provider's budget for getSignatureStatuses, B calls in any window W (keyless: 40 in 10 s;
// one signature a read, so no request links two of the user's wallets: n txs cost n reads a round). Counted, not timed,
// so a fast round trip spends no more:
// - each set's first C = B/5 reads are its burst (keyless 8), spaced by pollMs over its open txs and spread over at
//   least FILL_BURST_MS (most txs land within it): a 3-tx sell landing 0.8 s in is read filled about 0.6 s after;
// - after it, the set reads no faster than the steady pool, B - 2C in any W (keyless 24, one read every 417 ms), and
//   every set's steady reads on the provider share that one pool (RpcQueue.fillSteady);
// - so a set's own reads in any window are at most C + (B - 2C) = B - C, and with every steady read held to B - 2C
//   at least C stay free for a set that starts later: its whole burst goes at once, whatever ran before (two at once
//   once the older set's burst has left the window).
// A lone open tx of an n-tx set is read again at least every n x max(pollMs / n, W / (B - 2C)) plus the round trip
// (keyless, 9 txs: 3.75 s; 3 txs: 1.25 s; 1 tx: 0.42 s).
const FILL_BURST_MS = 1_600;
const fillBurst = (l: SolanaRpcLimit): number => Math.max(1, Math.floor(l.perMethod / 5));
const fillPool = (l: SolanaRpcLimit): number => Math.max(1, l.perMethod - 2 * fillBurst(l));
/** Provider A's and B's requests a second when keyed; undefined in a place holds that provider to the keyless limit. */
export type SolanaProviderRps = readonly [number | undefined, number | undefined];
/** Each provider's limit: its requests a second when the caller names them (a keyed provider), else the keyless one. */
export function solanaProviderLimits(providerRps?: SolanaProviderRps): readonly [SolanaRpcLimit, SolanaRpcLimit] {
  if (providerRps === undefined) return [SOLANA_KEYLESS_RPC_LIMIT, SOLANA_KEYLESS_RPC_LIMIT];
  if (!Array.isArray(providerRps) || providerRps.length !== 2 || !providerRps.every((r) => r === undefined || (Number.isSafeInteger(r) && r > 0))) throw new Error("providerRps must be two whole numbers above 0, or undefined for a keyless provider");
  const one = (r: number | undefined) => (r === undefined ? SOLANA_KEYLESS_RPC_LIMIT : solanaRpsLimit(r));
  return [one(providerRps[0]), one(providerRps[1])];
}
/** Whether two providers are the same one: the same function under any wrapping, or the same URL. */
export function solanaSameProvider(a: SolanaRpc, b: SolanaRpc): boolean {
  return (bareOf.get(a) ?? a) === (bareOf.get(b) ?? b) || (a.url !== undefined && b.url !== undefined && urlKey(a.url) === urlKey(b.url));
}
/** The provider with every call in its shared queue (SOLANA_KEYLESS_RPC_LIMIT when no limit is named). */
export function solanaPacedRpc(rpc: SolanaRpc, limit: SolanaRpcLimit = SOLANA_KEYLESS_RPC_LIMIT): SolanaRpc {
  const bare = bareOf.get(rpc) ?? rpc;
  queueWith(bare, limit);
  const paced = (method: string, params: readonly unknown[]): Promise<unknown> => {
    const s = rpcSlot(bare, limit, method);
    // a call its limit allows now starts in this tick, as the bare provider's would
    return s.wait ? s.wait.then(() => s.run(params)) : s.run(params);
  };
  const out: SolanaRpc = bare.url === undefined ? paced : Object.assign(paced, { url: bare.url });
  bareOf.set(out, bare);
  return out;
}

export type SolanaFetch = (url: string, init: RequestInit) => Promise<Response>;
/** One JSON-RPC call on one Solana provider: resolves the call's `result`, rejects on any other answer. `url`, when
 * set (solanaJsonRpc sets it), is what tells two providers apart; the set send refuses two with the same one. */
export type SolanaRpc = ((method: string, params: readonly unknown[]) => Promise<unknown>) & { readonly url?: string };
/** One send path: posts the base64 bytes, resolves the signature the path answered. A path with `minIntervalMs` gets
 * one tx per that interval, rotating through the set; one without gets every tx every rebroadcast. */
export type SolanaSendPath = {
  readonly name: string;
  readonly send: (base64Tx: string) => Promise<string>;
  readonly minIntervalMs?: number;
  /** Paths with the same paceKey (the URL, for solanaSendPaths' own) share one pacer across every set in flight. */
  readonly paceKey?: string;
};
/** A tx the device signed, and the lastValidBlockHeight of its blockhash from the device's own getLatestBlockhash. */
export type SolanaSignedTx = { readonly wire: Uint8Array; readonly lastValidBlockHeight: number };

export type SolanaSendAttempt = { path: string; attempt: number; ok: boolean; ms: number; error?: string };
export type SolanaTxState = "filled" | "failed" | "expired" | "unknown";
export type SolanaTxOutcome = {
  signature: string;
  state: SolanaTxState;
  /** The landed slot as provider A read it, when filled or failed. */
  slot?: number;
  /** Each provider's error, when failed. */
  err?: readonly [unknown, unknown];
  /** From the first send to the read that decided it. */
  ms?: number;
  sends: SolanaSendAttempt[];
};
export type SolanaSetResult = { txs: SolanaTxOutcome[] };
export type SolanaSetHandle = {
  readonly signatures: readonly string[];
  readonly done: Promise<SolanaSetResult>;
  /** Stops every send and read now; undecided txs end "unknown". */
  stop(): void;
};
export type SolanaSetOptions = {
  readonly paths: readonly SolanaSendPath[];
  /** Provider A (device-direct) and provider B, as the quote checks read them. */
  readonly providers: readonly [SolanaRpc, SolanaRpc];
  readonly rebroadcastMs?: number;
  readonly pollMs?: number;
  readonly deadlineMs?: number;
  readonly callTimeoutMs?: number;
  /** A keyed provider's requests a second, every call on it counted, this set's and every other caller's; a provider
   * not named here (absent, or undefined in its place) is held to SOLANA_KEYLESS_RPC_LIMIT. */
  readonly providerRps?: SolanaProviderRps;
};

const errText = (e: unknown): string => String(e instanceof Error ? e.message : e).slice(0, 200);

function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
  let t: ReturnType<typeof setTimeout> | undefined;
  return Promise.race([p, new Promise<never>((_, rej) => { t = setTimeout(() => rej(new Error(`no answer in ${ms} ms`)), ms); })]).finally(() => clearTimeout(t));
}

async function readBounded(r: Response): Promise<string> {
  if (Number(r.headers.get("content-length") ?? "0") > SOLANA_ANSWER_MAX_BYTES) throw new Error("answer too large");
  if (!r.body) return "";
  const reader = r.body.getReader();
  const parts: Uint8Array[] = [];
  let n = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    n += value.byteLength;
    if (n > SOLANA_ANSWER_MAX_BYTES) {
      void reader.cancel().catch(() => {});
      throw new Error("answer too large");
    }
    parts.push(value);
  }
  const all = new Uint8Array(n);
  let o = 0;
  for (const p of parts) { all.set(p, o); o += p.byteLength; }
  return new TextDecoder().decode(all);
}

function httpsUrl(raw: string, what: string): URL {
  let u: URL;
  try { u = new URL(raw); } catch { throw new Error(`${what} must be an https URL`); }
  const loopback = u.hostname === "localhost" || u.hostname === "127.0.0.1" || u.hostname === "[::1]";
  if (u.protocol !== "https:" && !(u.protocol === "http:" && loopback)) throw new Error(`${what} must be an https URL`);
  if (u.username || u.password || u.hash) throw new Error(`${what} must carry no credentials or fragment`);
  return u;
}

let nextId = 1;
/** JSON-RPC over HTTP POST to one URL. `init` is merged into every request (the helper's HELPER_FETCH_INIT). The id is
 * a string of digits, so an echo of it as the string or as the same number both match, and nothing else does. */
export function solanaJsonRpc(url: string, opts: { fetch?: SolanaFetch; init?: RequestInit; timeoutMs?: number } = {}): SolanaRpc {
  const href = httpsUrl(url, "an RPC URL").href;
  const doFetch: SolanaFetch = opts.fetch ?? ((u, i) => fetch(u, i));
  const timeoutMs = opts.timeoutMs ?? SOLANA_CALL_TIMEOUT_MS;
  const call = (method: string, params: readonly unknown[]): Promise<unknown> => {
    const id = String(nextId++);
    const init: RequestInit = {
      ...opts.init,
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", id, method, params }),
      signal: AbortSignal.timeout(timeoutMs),
    };
    // fetch is called here, synchronously: a caller that starts several calls starts them all in one tick.
    return doFetch(url, init).then(async (r) => {
      const text = await readBounded(r);
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const j = JSON.parse(text) as unknown;
      if (typeof j !== "object" || j === null || Array.isArray(j)) throw new Error("not a JSON-RPC answer");
      const o = j as Record<string, unknown>;
      if (!(o.id === id || (typeof o.id === "number" && String(o.id) === id))) throw new Error(`answer id ${JSON.stringify(o.id)} is not request id ${id}`);
      if (o.error !== undefined) {
        const e = o.error as { code?: unknown; message?: unknown } | null;
        throw new Error(`RPC error ${String(e?.code)}: ${String(e?.message).slice(0, 120)}`);
      }
      if (!("result" in o)) throw new Error("no result");
      return o.result;
    });
  };
  return Object.assign(call, { url: href });
}

/** The helper's POST /v1/rpc/solana (helper/v1.ts HELPER_RPC_METHODS: sendTransaction, getSignatureStatuses,
 * getLatestBlockhash and isBlockhashValid are on its list), with the kit's HELPER_FETCH_INIT. `origin` is the helper's origin only. */
export function solanaHelperRpc(origin: string, opts: { fetch?: SolanaFetch; timeoutMs?: number } = {}): SolanaRpc {
  const u = httpsUrl(origin, "the helper origin");
  if (u.pathname !== "/" || u.search !== "" || !(origin === u.origin || origin === `${u.origin}/`)) throw new Error("the helper origin must be an origin only");
  return solanaJsonRpc(`${u.origin}${HELPER_V1_PREFIX}/rpc/solana`, { ...opts, init: HELPER_FETCH_INIT });
}

const SEND_CONFIG = { encoding: "base64", skipPreflight: true, maxRetries: 0 } as const;

function rpcPath(name: string, rpc: SolanaRpc, config: Record<string, unknown>, minIntervalMs?: number): SolanaSendPath {
  return {
    name,
    ...(minIntervalMs === undefined ? {} : { minIntervalMs, ...(rpc.url ? { paceKey: rpc.url } : {}) }),
    send: (b64) => solanaPacedRpc(rpc)("sendTransaction", [b64, config]).then((sig) => {
      if (typeof sig !== "string") throw new Error("the path answered no signature");
      return sig;
    }),
  };
}

/**
 * The paper's send paths: Sender, Jito and a public RPC from the device, keyless, and the helper's keyed send when
 * the app has a helper. With no helper the set goes on three paths; nothing waits for a fourth.
 */
export function solanaSendPaths(opts: { helper?: SolanaRpc | null; rpcUrl?: string; fetch?: SolanaFetch; timeoutMs?: number } = {}): SolanaSendPath[] {
  const o = { ...(opts.fetch ? { fetch: opts.fetch } : {}), ...(opts.timeoutMs ? { timeoutMs: opts.timeoutMs } : {}) };
  const paths = [
    rpcPath("sender", solanaJsonRpc(SOLANA_SENDER_FAST_URL, o), SEND_CONFIG, SOLANA_KEYLESS_PATH_INTERVAL_MS),
    rpcPath("jito", solanaJsonRpc(SOLANA_JITO_TRANSACTIONS_URL, o), { encoding: "base64" }, SOLANA_KEYLESS_PATH_INTERVAL_MS),
    rpcPath("rpc", solanaJsonRpc(opts.rpcUrl ?? SOLANA_PUBLIC_RPC_URL, o), SEND_CONFIG),
  ];
  if (opts.helper) paths.push(rpcPath("helper", opts.helper, SEND_CONFIG));
  return paths;
}

// One pacer per 1-rps URL (or per path object without a paceKey), shared by every set in flight: at most one request
// per interval, each turn going to the next set that has a tx to send. A request is never sent sooner than one
// interval after the last; a set that joins a pacer idle for an interval sends at once.
type PaceClient = () => (() => void) | null;
type Pacer = {
  interval: number;
  last: number;
  idleUntil: number;
  clients: PaceClient[];
  turn: number;
  timer: ReturnType<typeof setTimeout> | undefined;
  /** Set while the pacer has no client: it leaves the map one interval after its last request, not sooner, so a set
   * that starts right after another on the same URL still waits out that URL's second. */
  dropTimer: ReturnType<typeof setTimeout> | undefined;
};
const pacers = new Map<unknown, Pacer>();

/** How many 1-rps pacers this page holds: a diagnostic read (the kit's tests check that a finished set's pacer goes). */
export function solanaSendPacerCount(): number {
  return pacers.size;
}
/** How many turns the provider's queue holds, booked (not yet started) and started (in the last minute), of one method
 * when named: a diagnostic read (the kit's tests check that a turn given up on leaves none behind, and that the fill
 * poll books none while it reads). */
export function solanaRpcQueueSize(rpc: SolanaRpc, method?: string): { booked: number; started: number } {
  const bare = bareOf.get(rpc) ?? rpc;
  const q = bare.url === undefined ? queueOfFn.get(bare) : queueOfUrl.get(urlKey(bare.url));
  const slots = (q?.slots ?? []).filter((x) => method === undefined || x.method === method);
  return { booked: slots.filter((x) => !x.started).length, started: slots.filter((x) => x.started).length };
}

function paceFire(p: Pacer): boolean {
  const n = p.clients.length;
  for (let k = 0; k < n; k++) {
    const send = p.clients[(p.turn + k) % n]!();
    if (send) {
      p.turn = (p.turn + k + 1) % n;
      p.last = Date.now();
      send();
      return true;
    }
  }
  return false;
}

function paceArm(p: Pacer): void {
  if (p.timer !== undefined || p.clients.length === 0) return;
  const now = Date.now();
  if (p.last > now) p.last = -Infinity; // a clock that went back
  if (p.idleUntil > now + p.interval) p.idleUntil = 0;
  p.timer = setTimeout(() => {
    p.timer = undefined;
    const t = Date.now();
    // A timer that fires early (some browsers do, by a millisecond) sends nothing and re-arms for the rest.
    if (t - p.last >= p.interval && !paceFire(p)) p.idleUntil = t + p.interval; // nothing to send: look again in one interval
    paceArm(p);
  }, Math.max(0, p.last + p.interval - now, p.idleUntil - now));
}

/** Joins `client` to the pacer of `key`; returns the leave call. */
function paceJoin(key: unknown, interval: number, client: PaceClient): () => void {
  let p = pacers.get(key);
  if (!p) {
    p = { interval, last: -Infinity, idleUntil: 0, clients: [], turn: 0, timer: undefined, dropTimer: undefined };
    pacers.set(key, p);
  }
  const pacer = p;
  if (pacer.dropTimer !== undefined) {
    clearTimeout(pacer.dropTimer);
    pacer.dropTimer = undefined;
  }
  pacer.interval = Math.max(pacer.interval, interval);
  pacer.clients.push(client);
  const now = Date.now();
  if (pacer.last > now) pacer.last = -Infinity;
  pacer.idleUntil = 0;
  if (now - pacer.last >= pacer.interval && paceFire(pacer) && pacer.timer !== undefined) {
    clearTimeout(pacer.timer);
    pacer.timer = undefined;
  }
  paceArm(pacer);
  return () => {
    const i = pacer.clients.indexOf(client);
    if (i >= 0) pacer.clients.splice(i, 1);
    if (pacer.clients.length > 0) return;
    if (pacer.timer !== undefined) {
      clearTimeout(pacer.timer);
      pacer.timer = undefined;
    }
    const drop = () => {
      pacer.dropTimer = undefined;
      if (pacer.clients.length === 0 && pacers.get(key) === pacer) pacers.delete(key);
    };
    const wait = pacer.last + pacer.interval - Date.now();
    if (wait <= 0 || pacer.last > Date.now()) drop();
    else if (pacer.dropTimer === undefined) pacer.dropTimer = setTimeout(drop, wait);
  };
}

type Prepared = { signature: string; b64: string; lvbh: number; blockhash: string };

/** The set's own checks before anything is sent: signed bytes the kit can decode, each once, a usable height. */
function prepare(set: readonly SolanaSignedTx[], opts: Pick<SolanaSetOptions, "paths" | "providers" | "providerRps">): Prepared[] {
  if (!Array.isArray(set) || set.length === 0) throw new Error("the set is empty");
  if (!Array.isArray(opts.paths) || opts.paths.length === 0) throw new Error("no send path");
  if (!Array.isArray(opts.providers) || opts.providers.length !== 2 || typeof opts.providers[0] !== "function" || typeof opts.providers[1] !== "function") throw new Error("two providers are needed");
  const [pa, pb] = opts.providers;
  if (solanaSameProvider(pa, pb)) throw new Error("the two providers are the same provider: a fill must never rest on one provider's word");
  // Each provider's limit named in its queue before the set's first call (its sends on an RPC path to the same URL too).
  const limits = solanaProviderLimits(opts.providerRps);
  queueWith(pa, limits[0]);
  queueWith(pb, limits[1]);
  for (const p of opts.paths) {
    if (p.minIntervalMs !== undefined && !(Number.isSafeInteger(p.minIntervalMs) && p.minIntervalMs > 0)) throw new Error(`path ${p.name}: minIntervalMs ${String(p.minIntervalMs)}`);
  }
  const seen = new Set<string>();
  return set.map((t, i) => {
    if (!(t?.wire instanceof Uint8Array)) throw new Error(`tx ${i}: no wire bytes`);
    if (t.wire.length > SOLANA_MAX_TX_BYTES) throw new Error(`tx ${i}: ${t.wire.length} bytes, over ${SOLANA_MAX_TX_BYTES}`);
    const decoded = solanaDecodeTransaction(t.wire); // throws on bytes that are not one whole transaction
    if (decoded.signatures < 1 || decoded.signatures > 0x7f) throw new Error(`tx ${i}: ${decoded.signatures} signature slots`);
    for (let s = 0; s < decoded.signatures; s++) {
      if (t.wire.subarray(1 + 64 * s, 65 + 64 * s).every((b: number) => b === 0)) throw new Error(`tx ${i}: signature ${s} is not signed`);
    }
    // A durable-nonce tx (first instruction System AdvanceNonceAccount, u32 LE 4; Agave's get_durable_nonce) never
    // expires by height, so lastValidBlockHeight says nothing of it.
    const first = decoded.message.instructions[0];
    const d = first?.data;
    if (first && decoded.message.staticKeys[first.programIndex] === SOLANA_SYSTEM_PROGRAM && d && d.length >= 4 && d[0] === 4 && d[1] === 0 && d[2] === 0 && d[3] === 0) throw new Error(`tx ${i}: a durable nonce tx has no lastValidBlockHeight`);
    if (!Number.isSafeInteger(t.lastValidBlockHeight) || t.lastValidBlockHeight < 0 || t.lastValidBlockHeight >= 2 ** 53 - 1) throw new Error(`tx ${i}: lastValidBlockHeight ${String(t.lastValidBlockHeight)}`);
    const signature = base58.encode(t.wire.subarray(1, 65));
    if (seen.has(signature)) throw new Error(`tx ${i}: the same tx is in the set twice`);
    seen.add(signature);
    return { signature, b64: base64.encode(t.wire), lvbh: t.lastValidBlockHeight, blockhash: decoded.message.blockhash };
  });
}

// One provider's read of one signature, after the shape checks.
type Read = "none" | "pending" | "ok" | "err" | "bad";
type StatusRead = { kind: Read; slot?: number; err?: unknown };
const STATUSES = new Set(["processed", "confirmed", "finalized"]);
const isSlot = (v: unknown): v is number => typeof v === "number" && Number.isSafeInteger(v) && v >= 0;

/** A getSignatureStatuses answer for n signatures: each read, and the slot of the bank that answered; null when the
 * answer is not one. */
function readStatuses(answer: unknown, n: number): { reads: StatusRead[]; slot: number } | null {
  if (typeof answer !== "object" || answer === null) return null;
  const slot = (answer as { context?: { slot?: unknown } }).context?.slot;
  if (!isSlot(slot)) return null;
  const v = (answer as { value?: unknown }).value;
  if (!Array.isArray(v) || v.length !== n) return null;
  const reads = v.map((s): StatusRead => {
    if (s === null) return { kind: "none" };
    if (typeof s !== "object" || Array.isArray(s)) return { kind: "bad" };
    const o = s as Record<string, unknown>;
    if (typeof o.confirmationStatus !== "string" || !STATUSES.has(o.confirmationStatus) || !("err" in o) || !Number.isSafeInteger(o.slot)) return { kind: "bad" };
    if (o.confirmationStatus === "processed") return { kind: "pending" };
    return o.err === null ? { kind: "ok", slot: o.slot as number } : { kind: "err", slot: o.slot as number, err: o.err };
  });
  return { reads, slot };
}

/** A getLatestBlockhash answer at finalized: the bank's slot and block height. */
function readAnchor(answer: unknown): { slot: number; height: number } | null {
  if (typeof answer !== "object" || answer === null) return null;
  const a = answer as { context?: { slot?: unknown }; value?: { lastValidBlockHeight?: unknown } };
  const slot = a.context?.slot;
  const lvbh = a.value?.lastValidBlockHeight;
  if (!isSlot(slot) || !isSlot(lvbh) || lvbh < MAX_PROCESSING_AGE) return null;
  return { slot, height: lvbh - MAX_PROCESSING_AGE };
}

/** An isBlockhashValid answer: the bank's slot and the verdict. */
function readValid(answer: unknown): { slot: number; valid: boolean } | null {
  if (typeof answer !== "object" || answer === null) return null;
  const a = answer as { context?: { slot?: unknown }; value?: unknown };
  if (!isSlot(a.context?.slot) || typeof a.value !== "boolean") return null;
  return { slot: a.context.slot, valid: a.value };
}

/** One provider's reads for 06c A4: a landed status, its finalized bank (slot and height), the slot of the bank that
 * read the blockhash no longer valid at processed, and the slot of the bank of a searchTransactionHistory: true read
 * that had no status for the signature. */
export type SolanaDeadReads = {
  landed: boolean;
  anchor: { slot: number; height: number } | null;
  invalidAt: number | undefined;
  histNone: number | undefined;
};

/**
 * 06c A4 on one provider, the one rule the send loop (deadOn) and a later session's re-read (readSolanaTxEnd) decide
 * by: never landed there; its finalized bank's height past the tx's lastValidBlockHeight; the blockhash read no longer
 * valid at processed; and a history read with no status from a bank at or past both the anchor's slot and that
 * validity read's slot (a node that has not replayed the landing block cannot answer it). A tx is dead only when both
 * providers say so.
 */
export function solanaDeadOn(r: SolanaDeadReads, lastValidBlockHeight: number): boolean {
  if (!isSlot(lastValidBlockHeight) || r.landed || r.anchor === null || r.invalidAt === undefined || r.histNone === undefined) return false;
  return r.anchor.height > lastValidBlockHeight && r.histNone >= r.anchor.slot && r.histNone >= r.invalidAt;
}

/**
 * How a tx signed in an earlier session ended (a reload or a closed tab: its send loop is gone), read on both
 * providers, each in A4's order: its finalized bank, then the blockhash at processed, then the status with
 * searchTransactionHistory: true. filled or failed when both read it landed so; expired when solanaDeadOn holds on
 * both; unknown otherwise (one provider's word, an error or a lagging node decides nothing). The send loop also wants
 * a valid read of the blockhash before an invalid one counts, against a hash too fresh for a bank to hold; here the
 * invalid read counts only from a bank at or past that provider's finalized anchor, whose height is past the hash's
 * lastValidBlockHeight, so that bank comes after the hash and its no is the hash's age, not a bank that never held
 * it; and the signer records the higher lastValidBlockHeight of the two providers' reads (readSolanaBlockhashBoth),
 * so one provider cannot lower it.
 */
export async function readSolanaTxEnd(
  providers: readonly [SolanaRpc, SolanaRpc],
  tx: { signature: string; blockhash: string; lastValidBlockHeight: number },
  callTimeoutMs = SOLANA_CALL_TIMEOUT_MS,
): Promise<"filled" | "failed" | "expired" | "unknown"> {
  const one = async (rpc: SolanaRpc): Promise<{ read: StatusRead | null; dead: boolean }> => {
    try {
      const call = (method: string, params: readonly unknown[]) => withTimeout(Promise.resolve().then(() => rpc(method, params)), callTimeoutMs);
      const anchor = readAnchor(await call("getLatestBlockhash", [{ commitment: "finalized" }]));
      const v = readValid(await call("isBlockhashValid", [tx.blockhash, { commitment: "processed" }]));
      const st = readStatuses(await call("getSignatureStatuses", [[tx.signature], { searchTransactionHistory: true }]), 1);
      if (!st) return { read: null, dead: false };
      const read = st.reads[0]!;
      const reads: SolanaDeadReads = {
        landed: read.kind === "ok" || read.kind === "err",
        anchor,
        // an invalid read counts only from a bank at or past this provider's finalized anchor: a bank behind it may
        // predate the blockhash, and with a lowered lastValidBlockHeight the height says nothing
        invalidAt: v && !v.valid && anchor !== null && v.slot >= anchor.slot ? v.slot : undefined,
        histNone: read.kind === "none" ? st.slot : undefined,
      };
      return { read, dead: solanaDeadOn(reads, tx.lastValidBlockHeight) };
    } catch {
      return { read: null, dead: false };
    }
  };
  const [a, b] = await Promise.all(providers.map(one));
  if (a!.read?.kind === "ok" && b!.read?.kind === "ok") return "filled";
  if (a!.read?.kind === "err" && b!.read?.kind === "err") return "failed";
  return a!.dead && b!.dead ? "expired" : "unknown";
}

/**
 * Sends a signed set on every path and reads its fills on two providers. Throws before any send when the set fails
 * its own checks; after that it never throws, and `done` resolves with one outcome per tx, in set order.
 */
export function sendSolanaSet(set: readonly SolanaSignedTx[], opts: SolanaSetOptions): SolanaSetHandle {
  const txs = prepare(set, opts);
  const rebroadcastMs = opts.rebroadcastMs ?? SOLANA_REBROADCAST_MS;
  const pollMs = opts.pollMs ?? SOLANA_STATUS_POLL_MS;
  if (!(typeof pollMs === "number" && Number.isFinite(pollMs) && pollMs > 0)) throw new Error("pollMs must be a number of ms above 0");
  const deadlineMs = opts.deadlineMs ?? SOLANA_SET_DEADLINE_MS;
  const callTimeoutMs = opts.callTimeoutMs ?? SOLANA_CALL_TIMEOUT_MS;
  const limits = solanaProviderLimits(opts.providerRps);
  const t0 = queueNow();
  const outcomes: SolanaTxOutcome[] = txs.map((t) => ({ signature: t.signature, state: "unknown", sends: [] }));
  const decided = txs.map(() => false);
  // Per provider:
  // - landed: the first landed read of each signature (ok or err). A confirmed tx stays confirmed, so a later null
  //   from a node behind a load balancer, or from a status cache that has dropped it, never takes a landing back.
  // - anchor: its finalized bank's slot and block height (one getLatestBlockhash answer, one bank).
  // - validMin: per blockhash, the lowest slot of a bank that read it valid at processed.
  // - invalidAt: per blockhash, the slot of the bank that read it as no longer valid at processed, counted only after
  //   a valid read from a bank at or below that slot: valid, then expired. A false with no valid read before it is no
  //   answer.
  // - histNone: per signature, the slot of the bank of the latest searchTransactionHistory: true read that had none.
  const landed = [new Map<string, StatusRead>(), new Map<string, StatusRead>()] as const;
  const chased = [new Set<string>(), new Set<string>()] as const; // txs read on p first because the other read them landed
  const burstLeft = [fillBurst(limits[0]), fillBurst(limits[1])]; // each provider's burst reads (fillBurst) not yet made
  const lastFast = [t0, t0]; // when a fill read last went out (or was booked) on each provider
  const anchor: [{ slot: number; height: number } | null, { slot: number; height: number } | null] = [null, null];
  const validMin = [new Map<string, number>(), new Map<string, number>()] as const;
  const invalidAt = [new Map<string, number>(), new Map<string, number>()] as const;
  const histNone = [new Map<string, number>(), new Map<string, number>()] as const;
  const fastInFlight = [false, false];
  // Per provider: the fill poll's round-robin position over the undecided txs.
  const fastCursor = [-1, -1];
  const deadInFlight = [false, false];
  const backoffMs = [0, 0];
  const backoffUntil = [0, 0];
  const pending = new Set<() => void>(); // the turns this set's calls wait for, given back when the set ends
  let attempt = 0;
  let over = false;
  let finish!: (r: SolanaSetResult) => void;
  const done = new Promise<SolanaSetResult>((r) => { finish = r; });

  const unlimited = opts.paths.filter((p) => p.minIntervalMs === undefined);
  const limited = opts.paths.filter((p) => p.minIntervalMs !== undefined);

  const pastOn = (p: 0 | 1, i: number): boolean => {
    const a = anchor[p];
    return a !== null && a.height > txs[i]!.lvbh && invalidAt[p].has(txs[i]!.blockhash);
  };
  const past = (i: number): boolean => pastOn(0, i) && pastOn(1, i);
  const eligible = (i: number): boolean => !decided[i] && !past(i);

  /** One call on provider p, in the provider's shared queue (rpcSlot), timed out, with its 429 back-off. Rejects on
   * any failure, and without calling once the set is over: a turn whose time comes after the end is given back.
   * end() gives back the turns pending then; every caller reads `over` before it asks, and this gives back a turn
   * asked after the end by a caller that did not (the dead check's loop once did, and its turn stayed booked). */
  function call(p: 0 | 1, method: string, params: readonly unknown[]): Promise<unknown> {
    const { run, wait, drop } = rpcSlot(opts.providers[p], limits[p], method);
    pending.add(drop);
    return (wait ?? Promise.resolve()).then(() => {
      pending.delete(drop);
      if (over) { drop(); throw new Error("the set is over"); }
      return withTimeout(Promise.resolve().then(() => run(params)), callTimeoutMs);
    }).then(
      (v) => { backoffMs[p] = 0; return v; },
      (e) => {
        if (/\b429\b/.test(errText(e))) {
          backoffMs[p] = Math.min(Math.max(backoffMs[p]! * 2, 1_000), BACKOFF_MAX_MS);
          backoffUntil[p] = queueNow() + backoffMs[p]!;
        }
        throw e;
      },
    );
  }
  const backedOff = (p: 0 | 1): boolean => queueNow() < backoffUntil[p]!;

  function sendOne(i: number, p: SolanaSendPath, n: number): void {
    const t = txs[i]!;
    const start = Date.now();
    let sent: Promise<string>;
    try {
      sent = p.send(t.b64);
    } catch (e) {
      sent = Promise.reject(e);
    }
    withTimeout(Promise.resolve(sent), callTimeoutMs).then(
      (sig) => {
        if (over) return; // the result is final once `done` resolves
        const ok = sig === t.signature;
        outcomes[i]!.sends.push({ path: p.name, attempt: n, ok, ms: Date.now() - start, ...(ok ? {} : { error: "the path answered another signature" }) });
      },
      (e) => { if (!over) outcomes[i]!.sends.push({ path: p.name, attempt: n, ok: false, ms: Date.now() - start, error: errText(e) }); },
    );
  }

  function broadcast(): void {
    const n = attempt++;
    for (let i = 0; i < txs.length; i++) if (eligible(i)) for (const p of unlimited) sendOne(i, p, n);
  }

  // Each 1-rps path: when its pacer gives this set a turn, the next eligible tx after the last it was given. The k-th
  // such path starts at tx k, so Sender and Jito carry different txs of a set in the same second.
  const cursor = limited.map((_, k) => k - 1);
  const limitedSent = limited.map(() => 0);
  const nextFor = (k: number): (() => void) | null => {
    if (over) return null;
    for (let step = 1; step <= txs.length; step++) {
      const i = (((cursor[k]! + step) % txs.length) + txs.length) % txs.length;
      if (!eligible(i)) continue;
      return () => {
        cursor[k] = i;
        sendOne(i, limited[k]!, limitedSent[k]!++);
      };
    }
    return null;
  };

  function record(p: 0 | 1, sig: string, r: StatusRead): void {
    if (r.kind !== "ok" && r.kind !== "err") return;
    if (!landed[p].has(sig)) landed[p].set(sig, r);
  }

  function deadOn(p: 0 | 1, i: number): boolean {
    const t = txs[i]!;
    return solanaDeadOn({ landed: landed[p].has(t.signature), anchor: anchor[p], invalidAt: invalidAt[p].get(t.blockhash), histNone: histNone[p].get(t.signature) }, t.lvbh);
  }

  function decide(): void {
    for (let i = 0; i < txs.length; i++) {
      if (decided[i]) continue;
      const sig = txs[i]!.signature;
      const ra = landed[0].get(sig);
      const rb = landed[1].get(sig);
      const o = outcomes[i]!;
      if (ra?.kind === "ok" && rb?.kind === "ok") {
        o.state = "filled";
        o.slot = ra.slot!;
      } else if (ra?.kind === "err" && rb?.kind === "err") {
        o.state = "failed";
        o.slot = ra.slot!;
        o.err = [ra.err, rb.err];
      } else if (deadOn(0, i) && deadOn(1, i)) {
        o.state = "expired";
      } else continue;
      o.ms = Math.round(queueNow() - t0);
      decided[i] = true;
    }
    if (decided.every(Boolean)) end();
  }

  /** getSignatureStatuses for one tx on p: one signature a request, never a batch, since each signature names its fee
   * payer, one of the user's wallets, and no request may carry two of them. Null when it is not an answer. */
  async function status(p: 0 | 1, i: number, history: boolean): Promise<{ r: StatusRead; slot: number } | null> {
    const ans = readStatuses(await call(p, "getSignatureStatuses", [[txs[i]!.signature], { searchTransactionHistory: history }]), 1);
    return ans ? { r: ans.reads[0]!, slot: ans.slot } : null;
  }

  // The fill poll: the status cache only (searchTransactionHistory: false), one undecided tx a call, in turn, the calls
  // spaced by fastPeriod. Whether a read went out.
  function readFast(p: 0 | 1): boolean {
    if (fastInFlight[p] || over || backedOff(p)) return false;
    // A tx p has read landed is not read again on p (its first read is the one kept); one the other provider has read
    // landed goes first, once, so the second read a fill needs follows the first at once; the rest in turn, so a tx
    // one provider never sees land never holds the others back.
    const open = (k: number): boolean => !decided[k] && !landed[p].has(txs[k]!.signature);
    let i = txs.findIndex((t, k) => open(k) && landed[p === 0 ? 1 : 0].has(t.signature) && !chased[p].has(t.signature));
    if (i >= 0) chased[p].add(txs[i]!.signature);
    else {
      for (let step = 1; step <= txs.length; step++) {
        const k = (fastCursor[p]! + step) % txs.length;
        if (open(k)) { i = k; break; }
      }
      if (i < 0) return false;
      fastCursor[p] = i;
    }
    fastInFlight[p] = true;
    status(p, i, false)
      .then((got) => {
        if (over || !got) return; // a broken answer is no answer
        record(p, txs[i]!.signature, got.r);
        decide();
      }, () => {})
      .finally(() => { fastInFlight[p] = false; });
    return true;
  }
  /** The fill poll's spacing on p: pollMs over the txs p still reads, and no closer than the steady pool allows
   * (W / (B - 2C)); a burst read, spread over FILL_BURST_MS, never further apart than a steady one. */
  const fastPeriod = (p: 0 | 1): number => {
    const n = Math.max(1, txs.filter((t, k) => !decided[k] && !landed[p].has(t.signature)).length); // the txs p still reads
    const l = limits[p];
    const steady = Math.max(pollMs / n, l.windowMs / fillPool(l));
    return burstLeft[p]! > 0 ? Math.min(steady, Math.max(pollMs / n, FILL_BURST_MS / fillBurst(l))) : steady;
  };

  // The dead check on p, every rebroadcast: the finalized bank's height and slot; every undecided tx's blockhash at
  // processed; for each tx past its lastValidBlockHeight there, a status read with searchTransactionHistory: true. Each step's answer carries its bank's slot, which deadOn compares.
  function readDead(p: 0 | 1): void {
    if (deadInFlight[p] || over || backedOff(p)) return;
    deadInFlight[p] = true;
    (async () => {
      const a = readAnchor(await call(p, "getLatestBlockhash", [{ commitment: "finalized" }]));
      if (a && (anchor[p] === null || (a.height >= anchor[p]!.height && a.slot >= anchor[p]!.slot))) anchor[p] = a; // never goes back
      if (over) return;
      // Every undecided tx's blockhash, from the first cycle on, so a fresh hash is read valid before it can read expired.
      const open = txs.map((_, i) => i).filter((i) => !decided[i]);
      for (const bh of new Set(open.map((i) => txs[i]!.blockhash))) {
        if (over) return;
        let answer: unknown;
        try {
          answer = await call(p, "isBlockhashValid", [bh, { commitment: "processed" }]);
        } catch {
          continue; // refused (a helper whose allowlist predates it), rate-limited or timed out: no answer, the cycle goes on
        }
        const v = readValid(answer);
        if (!v) continue;
        if (v.valid) {
          invalidAt[p].delete(bh);
          const m = validMin[p].get(bh);
          if (m === undefined || v.slot < m) validMin[p].set(bh, v.slot);
        } else {
          const m = validMin[p].get(bh);
          if (m !== undefined && m <= v.slot) invalidAt[p].set(bh, v.slot);
        }
      }
      const cur = anchor[p];
      if (over || cur === null) return;
      // Every tx past its lastValidBlockHeight on this bank is read with the history: it can find a landing the status
      // cache has dropped (a fill) whatever the blockhash reads; it counts toward dead only through deadOn's gates.
      const check = open.filter((i) => !decided[i] && cur.height > txs[i]!.lvbh);
      if (over || check.length === 0) return;
      for (const i of check) {
        if (over || decided[i]) continue;
        const got = await status(p, i, true);
        if (over) return;
        if (!got) continue;
        const sig = txs[i]!.signature;
        record(p, sig, got.r);
        if (got.r.kind === "none") histNone[p].set(sig, got.slot);
        else histNone[p].delete(sig);
      }
      decide();
    })()
      .catch(() => {})
      .finally(() => { deadInFlight[p] = false; });
  }

  broadcast(); // the first send, in this tick, before anything is awaited
  const leaves = limited.map((p, k) => paceJoin(p.paceKey ?? p, p.minIntervalMs!, () => nextFor(k)));
  const timers = [setInterval(() => { readDead(0); readDead(1); broadcast(); }, rebroadcastMs)];
  const fastTimers: (ReturnType<typeof setTimeout> | undefined)[] = [undefined, undefined];
  // Past its burst, a fill read goes only while the steady reads of every set on the provider are under the pool
  // (fillPool) in the window, else at the time the oldest of them leaves it.
  const fastTick = (p: 0 | 1): void => {
    if (over) return;
    // A fill read that would wait is not asked, so the calls waiting on p go first; but once no fill read has gone on p
    // for a whole window (a slow keyed provider whose budget the dead check's reads fill), the next one books its turn
    // behind them, so the poll reads at every limit.
    const waitMs = methodWaitMs(opts.providers[p], limits[p], "getSignatureStatuses");
    if (waitMs > 0 && queueNow() - lastFast[p]! < limits[p].windowMs) { fastTimers[p] = setTimeout(() => fastTick(p), waitMs); return; }
    if (burstLeft[p]! > 0) {
      if (readFast(p)) { burstLeft[p]!--; lastFast[p] = queueNow(); }
    } else {
      const l = limits[p];
      const q = queueWith(opts.providers[p], l);
      const now = queueNow();
      q.fillSteady = q.fillSteady.filter((x) => x > now - l.windowMs);
      if (q.fillSteady.length >= fillPool(l)) {
        fastTimers[p] = setTimeout(() => fastTick(p), q.fillSteady[0]! + l.windowMs - now + 1);
        return;
      }
      if (readFast(p)) { q.fillSteady.push(now); lastFast[p] = now; }
    }
    fastTimers[p] = setTimeout(() => fastTick(p), fastPeriod(p));
  };
  fastTimers[0] = setTimeout(() => fastTick(0), fastPeriod(0));
  fastTimers[1] = setTimeout(() => fastTick(1), fastPeriod(1));
  const deadline = setTimeout(end, deadlineMs);

  function end(): void {
    if (over) return;
    over = true;
    for (const drop of pending) drop();
    pending.clear();
    for (const t of timers) clearInterval(t);
    for (const t of fastTimers) clearTimeout(t);
    for (const leave of leaves) leave();
    clearTimeout(deadline);
    finish({ txs: outcomes });
  }

  return { signatures: txs.map((t) => t.signature), done, stop: end };
}

export type SolanaDryTx = {
  signature: string;
  state: "simulated" | "sim-failed";
  /** Each provider's simulation: its error (null when clean) and compute units, or why it gave none. */
  simulations: readonly [{ err: unknown; units: number | null } | { error: string }, { err: unknown; units: number | null } | { error: string }];
};

/**
 * The --dry form (row M1.3's proof): the set's own checks, then each tx simulated on both providers
 * (simulateTransaction, sigVerify off, the blockhash replaced, at `confirmed`). No path is called and nothing is sent.
 * `paths` names the paths a real send would use, each getting the same base64 the simulations read.
 */
export async function dryRunSolanaSet(set: readonly SolanaSignedTx[], opts: SolanaSetOptions): Promise<{ paths: string[]; txs: SolanaDryTx[] }> {
  const txs = prepare(set, opts);
  const timeoutMs = opts.callTimeoutMs ?? SOLANA_CALL_TIMEOUT_MS;
  const config = { encoding: "base64", sigVerify: false, replaceRecentBlockhash: true, commitment: "confirmed" };
  const limits = solanaProviderLimits(opts.providerRps);
  const one = (p: 0 | 1, b64: string) => {
    const { run, wait } = rpcSlot(opts.providers[p], limits[p], "simulateTransaction");
    return (wait ?? Promise.resolve()).then(() => withTimeout(Promise.resolve().then(() => run([b64, config])), timeoutMs)).then(
      (ans) => {
        const v = (ans as { value?: { err?: unknown; unitsConsumed?: unknown } } | null)?.value;
        if (typeof v !== "object" || v === null || !("err" in v)) return { error: "not a simulation answer" };
        return { err: v.err, units: Number.isSafeInteger(v.unitsConsumed) ? (v.unitsConsumed as number) : null };
      },
      (e) => ({ error: errText(e) }),
    );
  };
  const out = await Promise.all(
    txs.map(async (t): Promise<SolanaDryTx> => {
      const sims = (await Promise.all([one(0, t.b64), one(1, t.b64)])) as SolanaDryTx["simulations"];
      const clean = sims.every((s) => "err" in s && s.err === null);
      return { signature: t.signature, state: clean ? "simulated" : "sim-failed", simulations: sims };
    }),
  );
  return { paths: opts.paths.map((p) => p.name), txs: out };
}

packages/kit/src/trade/solana/build.ts.body:
// The Solana swap build (markets paper T2.1 "Quote" and "Tx shape", docs/plan1/markets.md l.291-336; row M1.1).
// Device side. Jupiter's GET /swap/v2/build is asked through the helper's POST /v1/proxy/jupiter/swap/v2/build, which
// adds the key; the device then assembles the v0 transaction itself. Nothing in the build answer is trusted for what
// is signed: the answer only proposes instructions, and checkSolanaQuote (T2.2, S1-S13) judges the assembled bytes.
//
// - Query: inputMint, outputMint, amount = a_k, slippageBps, computeUnitPricePercentile=veryHigh, maxAccounts=40,
//   taker = W_k. When the cap finds no route (Jupiter answers 400 "No routes found"), one retry runs without
//   maxAccounts (P4S run 3, Fail 3); any other answer is never retried here.
// - Blockhash: the device's own getLatestBlockhash at `finalized`, never the build's blockhashWithMetadata (the
//   solana-set-send review), so the lastValidBlockHeight the send judges expiry by is one the device read itself.
// - Lookup tables: the build names them; their contents come only from the device's own reads (S2), passed in.
// - Frame (T2.1, 06c S-1 and S-2): 0 SetComputeUnitLimit (the route cap S8 applies: a one-step pump.fun curve route
//   200,000 on a buy step and 150,000 on a sell step, every other route 600,000), 1 SetComputeUnitPrice (Jupiter's
//   veryHigh estimate, capped at 1,000,000 micro-lamports per unit), Jupiter's setup, the wallet's own output account
//   (CreateIdempotent) on a buy when the setup has none, the swap, a CloseAccount to W_k for every account the setup
//   created that nothing closes (6a; a Token-2022 account of a mint the caller names as holding a transfer fee gets
//   HarvestWithheldTokensToMint right before it), Jupiter's cleanup, Jupiter's other instructions, then a 5,000-lamport
//   tip to a baked Helius Sender account and a 10,000-lamport tip to a baked Jito account.
// - Size: the unsigned wire (one zeroed signature slot) at most SOLANA_MAX_TX_BYTES = 1,232, else refused (S9).
//
// Every answer is hostile input: size-bounded, shape-checked; anything else is SolanaBuildError("bad_answer").
import { base58, base64 } from "@scure/base";
import { HELPER_FETCH_INIT, HELPER_V1_PREFIX } from "../../helper/v1.ts";
import { SOLANA_ATA_PROGRAM, SOLANA_MAX_TX_BYTES, solanaAta, solanaTableIsActive, type SolanaLookupTable } from "../../checks/solana/message.ts";
import {
  SOLANA_COMPUTE_BUDGET_PROGRAM,
  SOLANA_CU_PRICE_MAX,
  SOLANA_JITO_TIP,
  SOLANA_JITO_TIP_ACCOUNTS,
  SOLANA_SENDER_TIP,
  SOLANA_SENDER_TIP_ACCOUNTS,
  SOLANA_SOL_MINT,
  SOLANA_SYSTEM_PROGRAM,
  SOLANA_TOKEN_2022_PROGRAM,
  SOLANA_TOKEN_PROGRAM,
  SOLANA_CLOSE_VOLUME_ACCUMULATOR,
  SOLANA_TEARDOWN_CU,
  solanaEventAuthority,
  solanaRouteCuCap,
  type SolanaTeardownPlan,
  type SolanaTeardownSimulation,
} from "../../checks/solana/checks.ts";
import type { SolanaFetch, SolanaRpc } from "./send.ts";

/** The vendor path on the helper's proxy (apps/helper/src/proxy/vendors.ts, jupiter "/swap/v2/build": GET). */
export const SOLANA_JUPITER_BUILD_PROXY_PATH = `${HELPER_V1_PREFIX}/proxy/jupiter/swap/v2/build`;
/** The first build's account cap (P4S run 1, Fail 1: an uncapped route overran 1,232 bytes once our instructions rode on top). */
export const SOLANA_JUPITER_MAX_ACCOUNTS = 40;
/** Jupiter's answer when no route fits (P4S run 3, Fail 3; read through the helper 2026-11-02 04:58Z: 400 {"error":"No routes found"}). */
export const SOLANA_JUPITER_NO_ROUTE = "No routes found";
/** One build call is given up after this. */
export const SOLANA_BUILD_TIMEOUT_MS = 5_000;
/** A build is a few KB; its lookup-table lists, which the device never uses, are the bulk (3 tables of ~250 keys ~ 35 KB). */
export const SOLANA_BUILD_ANSWER_MAX_BYTES = 256 * 1024;

const MAX_INSTRUCTION_ACCOUNTS = 256;
const MAX_INSTRUCTION_DATA = SOLANA_MAX_TX_BYTES;
const MAX_SETUP = 16;
const MAX_OTHER = 8;
const MAX_BUDGET = 4;
const MAX_TABLES = 8;
const MAX_ROUTE_STEPS = 16;

export type SolanaBuildErrorCode = "no_route" | "upstream" | "bad_answer" | "too_large";
export class SolanaBuildError extends Error {
  readonly code: SolanaBuildErrorCode;
  constructor(code: SolanaBuildErrorCode, message: string) {
    super(`${code}: ${message}`);
    this.code = code;
    this.name = "SolanaBuildError";
  }
}
const bad = (m: string): never => {
  throw new SolanaBuildError("bad_answer", m);
};

/** What the device asks Jupiter to build: the user's own request for one wallet. */
export type SolanaBuildRequest = {
  side: "buy" | "sell";
  wallet: string; // W_k, the taker, fee payer and only signer
  token: string; // the token the user tapped
  amount: bigint; // a_k: lamports on a buy, the token's base units on a sell
  slippageBps: number; // set by the buy flow so that the decoded floor is at least minOut_k (T2.1, §1.3)
};

export type SolanaApiAccount = { readonly key: string; readonly signer: boolean; readonly writable: boolean };
export type SolanaApiInstruction = { readonly program: string; readonly accounts: readonly SolanaApiAccount[]; readonly data: Uint8Array };
/** The build answer, shape-checked. Only instructions and table addresses are kept; amounts and quotes are not read. */
export type SolanaJupiterBuild = {
  readonly cuPrice: bigint;
  readonly setup: readonly SolanaApiInstruction[];
  readonly swap: SolanaApiInstruction;
  readonly cleanup: SolanaApiInstruction | null;
  readonly other: readonly SolanaApiInstruction[];
  /** The tables the build names; the device reads their contents itself. */
  readonly tables: readonly string[];
  /** Venue labels from routePlan, for display only. */
  readonly route: readonly string[];
};
export type SolanaBuildCall = { maxAccounts: number | null; status: number; ms: number };
export type SolanaBuildFetched = { build: SolanaJupiterBuild; uncapped: boolean; calls: SolanaBuildCall[] };

const isKey = (v: unknown): v is string => {
  if (typeof v !== "string" || v.length < 32 || v.length > 44) return false;
  try {
    return base58.decode(v).length === 32;
  } catch {
    return false;
  }
};
const obj = (v: unknown, what: string): Record<string, unknown> => (typeof v === "object" && v !== null && !Array.isArray(v) ? (v as Record<string, unknown>) : bad(`${what} is not an object`));
const arr = (v: unknown, what: string, max: number): unknown[] => {
  if (!Array.isArray(v)) return bad(`${what} is not an array`);
  if (v.length > max) bad(`${what} has ${v.length} entries (at most ${max})`);
  return v;
};

function instruction(v: unknown, what: string): SolanaApiInstruction {
  const o = obj(v, what);
  if (!isKey(o.programId)) bad(`${what}.programId is not an address`);
  const accounts = arr(o.accounts, `${what}.accounts`, MAX_INSTRUCTION_ACCOUNTS).map((a, i) => {
    const x = obj(a, `${what}.accounts[${i}]`);
    if (!isKey(x.pubkey) || typeof x.isSigner !== "boolean" || typeof x.isWritable !== "boolean") bad(`${what}.accounts[${i}] is not { pubkey, isSigner, isWritable }`);
    return { key: x.pubkey as string, signer: x.isSigner as boolean, writable: x.isWritable as boolean };
  });
  if (typeof o.data !== "string" || o.data.length > Math.ceil(MAX_INSTRUCTION_DATA / 3) * 4) bad(`${what}.data is not base64 within ${MAX_INSTRUCTION_DATA} bytes`);
  let data: Uint8Array;
  try {
    data = base64.decode(o.data as string);
  } catch {
    return bad(`${what}.data is not base64`);
  }
  return { program: o.programId as string, accounts, data };
}

/** Shape-checks one /swap/v2/build answer. Throws SolanaBuildError("bad_answer") on anything else. */
export function parseSolanaJupiterBuild(answer: unknown): SolanaJupiterBuild {
  const o = obj(answer, "the build");
  const budget = arr(o.computeBudgetInstructions, "computeBudgetInstructions", MAX_BUDGET).map((x, i) => instruction(x, `computeBudgetInstructions[${i}]`));
  const price = budget.filter((ix) => ix.program === SOLANA_COMPUTE_BUDGET_PROGRAM && ix.accounts.length === 0 && ix.data.length === 9 && ix.data[0] === 3);
  if (price.length !== 1) bad(`${price.length} compute unit prices in the build (want 1)`);
  const p = new DataView((price[0] as SolanaApiInstruction).data.buffer, (price[0] as SolanaApiInstruction).data.byteOffset, 9).getBigUint64(1, true);
  const setup = arr(o.setupInstructions, "setupInstructions", MAX_SETUP).map((x, i) => instruction(x, `setupInstructions[${i}]`));
  const swap = instruction(o.swapInstruction, "swapInstruction");
  const cleanup = o.cleanupInstruction === null || o.cleanupInstruction === undefined ? null : instruction(o.cleanupInstruction, "cleanupInstruction");
  const other = (o.otherInstructions === undefined || o.otherInstructions === null ? [] : arr(o.otherInstructions, "otherInstructions", MAX_OTHER)).map((x, i) => instruction(x, `otherInstructions[${i}]`));
  const lists = o.addressesByLookupTableAddress === null || o.addressesByLookupTableAddress === undefined ? {} : obj(o.addressesByLookupTableAddress, "addressesByLookupTableAddress");
  const tables = Object.keys(lists);
  if (tables.length > MAX_TABLES) bad(`${tables.length} lookup tables (at most ${MAX_TABLES})`);
  for (const t of tables) if (!isKey(t)) bad(`lookup table ${String(t).slice(0, 50)} is not an address`);
  const route = (o.routePlan === undefined ? [] : arr(o.routePlan, "routePlan", MAX_ROUTE_STEPS)).map((s) => {
    const label = (s as { swapInfo?: { label?: unknown } } | null)?.swapInfo?.label;
    return typeof label === "string" ? label.slice(0, 64) : "?";
  });
  return { cuPrice: p < SOLANA_CU_PRICE_MAX ? p : SOLANA_CU_PRICE_MAX, setup, swap, cleanup, other, tables, route };
}

/** The /swap/v2/build query for one wallet, in a fixed order; maxAccounts is left out when null (the retry). */
export function solanaJupiterBuildQuery(req: SolanaBuildRequest, maxAccounts: number | null = SOLANA_JUPITER_MAX_ACCOUNTS): string {
  if (!isKey(req.wallet) || !isKey(req.token)) throw new Error("the wallet and the token must be addresses");
  if (req.token === SOLANA_SOL_MINT) throw new Error("the token cannot be native SOL");
  if (typeof req.amount !== "bigint" || req.amount <= 0n || req.amount > 0xffff_ffff_ffff_ffffn) throw new Error("the amount must be a u64 above 0");
  if (!Number.isInteger(req.slippageBps) || req.slippageBps < 0 || req.slippageBps > 10_000) throw new Error("slippageBps must be 0 to 10,000");
  const [inputMint, outputMint] = req.side === "buy" ? [SOLANA_SOL_MINT, req.token] : [req.token, SOLANA_SOL_MINT];
  const q = new URLSearchParams({ inputMint, outputMint, amount: req.amount.toString(), slippageBps: String(req.slippageBps), computeUnitPricePercentile: "veryHigh" });
  if (maxAccounts !== null) q.set("maxAccounts", String(maxAccounts));
  q.set("taker", req.wallet);
  return q.toString();
}

async function readCapped(r: Response, max: number): Promise<string> {
  if (Number(r.headers.get("content-length") ?? "0") > max) throw new SolanaBuildError("bad_answer", "the build answer is too large");
  if (!r.body) return "";
  const reader = r.body.getReader();
  const parts: Uint8Array[] = [];
  let n = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    n += value.byteLength;
    if (n > max) {
      void reader.cancel().catch(() => {});
      throw new SolanaBuildError("bad_answer", "the build answer is too large");
    }
    parts.push(value);
  }
  const all = new Uint8Array(n);
  let o = 0;
  for (const p of parts) { all.set(p, o); o += p.byteLength; }
  return new TextDecoder().decode(all);
}

function helperOrigin(origin: string): string {
  let u: URL;
  try { u = new URL(origin); } catch { throw new Error("the helper origin must be an https URL"); }
  const loopback = u.hostname === "localhost" || u.hostname === "127.0.0.1" || u.hostname === "[::1]";
  if (u.protocol !== "https:" && !(u.protocol === "http:" && loopback)) throw new Error("the helper origin must be an https URL");
  if (u.username || u.password || u.pathname !== "/" || u.search || u.hash || !(origin === u.origin || origin === `${u.origin}/`)) throw new Error("the helper origin must be an origin only");
  return u.origin;
}

/**
 * Asks the helper's proxy for Jupiter's build: maxAccounts=40 first, and one uncapped retry only when that answer is
 * Jupiter's 400 "No routes found". The retry's own "No routes found" is SolanaBuildError("no_route"); any other
 * non-200 answer (the helper's 503 upstream included) is "upstream" and is never retried here.
 */
export async function fetchSolanaJupiterBuild(
  origin: string,
  req: SolanaBuildRequest,
  opts: { fetch?: SolanaFetch; timeoutMs?: number; now?: () => number; uncapped?: boolean } = {},
): Promise<SolanaBuildFetched> {
  const base = helperOrigin(origin);
  const doFetch: SolanaFetch = opts.fetch ?? ((u, i) => fetch(u, i));
  const now = opts.now ?? (() => performance.now());
  const calls: SolanaBuildCall[] = [];
  const once = async (maxAccounts: number | null): Promise<{ status: number; body: unknown }> => {
    const url = `${base}${SOLANA_JUPITER_BUILD_PROXY_PATH}?${solanaJupiterBuildQuery(req, maxAccounts)}`;
    const t = now();
    let r: Response;
    let text: string;
    try {
      r = await doFetch(url, { ...HELPER_FETCH_INIT, method: "POST", redirect: "error", signal: AbortSignal.timeout(opts.timeoutMs ?? SOLANA_BUILD_TIMEOUT_MS) });
      text = await readCapped(r, SOLANA_BUILD_ANSWER_MAX_BYTES);
    } catch (e) {
      calls.push({ maxAccounts, status: 0, ms: now() - t });
      if (e instanceof SolanaBuildError) throw e;
      throw new SolanaBuildError("upstream", `the helper did not answer: ${String((e as Error)?.message ?? e).slice(0, 120)}`);
    }
    calls.push({ maxAccounts, status: r.status, ms: now() - t });
    let body: unknown;
    try {
      body = JSON.parse(text);
    } catch {
      throw new SolanaBuildError(r.status === 200 ? "bad_answer" : "upstream", `HTTP ${r.status}, not JSON`);
    }
    return { status: r.status, body };
  };
  const noRoute = (a: { status: number; body: unknown }) =>
    a.status === 400 && typeof a.body === "object" && a.body !== null && (a.body as { error?: unknown }).error === SOLANA_JUPITER_NO_ROUTE;
  // `uncapped`: the build asked without the cap from the start (the live check's uncapped shapes), with no retry.
  let uncapped = opts.uncapped === true;
  let a = await once(uncapped ? null : SOLANA_JUPITER_MAX_ACCOUNTS);
  if (uncapped && noRoute(a)) throw new SolanaBuildError("no_route", "no route uncapped");
  if (!uncapped && noRoute(a)) {
    uncapped = true;
    a = await once(null);
    if (noRoute(a)) throw new SolanaBuildError("no_route", `no route at maxAccounts=${SOLANA_JUPITER_MAX_ACCOUNTS} or uncapped`);
  }
  if (a.status !== 200) {
    const code = (a.body as { error?: unknown; errorCode?: unknown } | null)?.error;
    throw new SolanaBuildError("upstream", `HTTP ${a.status}${typeof code === "string" ? ` ${code.slice(0, 80)}` : ""}`);
  }
  return { build: parseSolanaJupiterBuild(a.body), uncapped, calls };
}

export type SolanaBlockhash = { blockhash: string; lastValidBlockHeight: number; slot: number };
/** The device's own blockhash: getLatestBlockhash at `finalized` on one of its providers. */
export async function readSolanaBlockhash(rpc: SolanaRpc): Promise<SolanaBlockhash> {
  const r = obj(await rpc("getLatestBlockhash", [{ commitment: "finalized" }]), "getLatestBlockhash");
  const ctx = obj(r.context, "getLatestBlockhash.context");
  const v = obj(r.value, "getLatestBlockhash.value");
  if (!isKey(v.blockhash) || !Number.isSafeInteger(v.lastValidBlockHeight) || (v.lastValidBlockHeight as number) <= 0 || !Number.isSafeInteger(ctx.slot) || (ctx.slot as number) <= 0) {
    bad("getLatestBlockhash answered no blockhash, lastValidBlockHeight and slot");
  }
  return { blockhash: v.blockhash as string, lastValidBlockHeight: v.lastValidBlockHeight as number, slot: ctx.slot as number };
}

// ---------------------------------------------------------------------------------------------------------------
// v0 assembly
// ---------------------------------------------------------------------------------------------------------------

const u32le = (n: number): number[] => [n & 0xff, (n >>> 8) & 0xff, (n >>> 16) & 0xff, (n >>> 24) & 0xff];
const u64le = (n: bigint): number[] => Array.from({ length: 8 }, (_, i) => Number((n >> BigInt(8 * i)) & 0xffn));
function compact(n: number): number[] {
  const out: number[] = [];
  let v = n;
  for (;;) {
    const b = v & 0x7f;
    v >>= 7;
    if (v === 0) { out.push(b); return out; }
    out.push(b | 0x80);
  }
}

/**
 * A v0 message from instructions, the fee payer and the tables, laid out as @solana/web3.js 1.98.4's
 * TransactionMessage.compileToV0Message does (src/message/compiled-keys.ts: keys in first-use order in a Map; the
 * kit's test holds the bytes web3.js made for a recorded two-table build). solana-sdk's v0::Message::try_compile keeps
 * its keys in a BTreeMap, so it orders them by address instead: a different, equally valid message. Every key once
 * with its signer and writable flags merged; a key that signs or is a program id stays static; any other key found in
 * a table is loaded from the first table that holds it (that table's writable then readonly indexes, in first-use
 * order); static keys are writable signers (the payer first), readonly signers, writable non-signers, readonly
 * non-signers; loaded keys follow, every table's writable entries, then every table's readonly. Only `signers` may
 * sign (the wallet alone for a swap; the fee payer and W for a pool release, src/trade/solana/pool-buy.ts). A Jito tip
 * account (SOLANA_JITO_TIP_ACCOUNTS) always stays static, even when a table holds it.
 */
export function solanaCompileV0(
  payer: string,
  ixs: readonly SolanaApiInstruction[],
  blockhash: string,
  tables: readonly { address: string; table: SolanaLookupTable }[],
  signers: readonly string[] = [payer],
): { message: Uint8Array; tablesUsed: string[] } {
  type Meta = { signer: boolean; writable: boolean; invoked: boolean };
  const meta = new Map<string, Meta>([[payer, { signer: true, writable: true, invoked: false }]]);
  const touch = (k: string, m: Partial<Meta>) => {
    const old = meta.get(k) ?? { signer: false, writable: false, invoked: false };
    meta.set(k, { signer: old.signer || !!m.signer, writable: old.writable || !!m.writable, invoked: old.invoked || !!m.invoked });
  };
  for (const ix of ixs) {
    touch(ix.program, { invoked: true });
    for (const a of ix.accounts) touch(a.key, { signer: a.signer, writable: a.writable });
  }
  for (const [k, m] of meta) if (m.signer && !signers.includes(k)) bad(`an instruction asks ${k} to sign (only ${signers.join(" and ")} sign)`);
  const lookups: { address: string; writable: number[]; readonly: number[]; wKeys: string[]; rKeys: string[] }[] = [];
  for (const { address, table } of tables) {
    const l = { address, writable: [] as number[], readonly: [] as number[], wKeys: [] as string[], rKeys: [] as string[] };
    for (const [k, m] of [...meta]) {
      // a Jito tip account is never loaded, whatever a table holds: "When tipping make sure to not use Address Lookup
      // Tables for the tip accounts" (docs.jito.wtf/lowlatencytxnsend, read 2026-11-03), so a block engine counts the tip (M362 (4))
      if (m.signer || m.invoked || SOLANA_JITO_TIP_ACCOUNTS.includes(k)) continue;
      const i = table.addresses.indexOf(k);
      if (i < 0 || i > 255) continue;
      if (m.writable) { l.writable.push(i); l.wKeys.push(k); } else { l.readonly.push(i); l.rKeys.push(k); }
      meta.delete(k);
    }
    if (l.writable.length + l.readonly.length) lookups.push(l);
  }
  const entries = [...meta];
  const group = (s: boolean, w: boolean) => entries.filter(([, m]) => m.signer === s && m.writable === w).map(([k]) => k);
  const staticKeys = [...group(true, true), ...group(true, false), ...group(false, true), ...group(false, false)];
  if (staticKeys[0] !== payer) bad("the fee payer is not the first key");
  const order = [...staticKeys, ...lookups.flatMap((l) => l.wKeys), ...lookups.flatMap((l) => l.rKeys)];
  if (order.length > 256) throw new SolanaBuildError("too_large", `${order.length} account keys`);
  const index = new Map(order.map((k, i) => [k, i]));
  const at = (k: string): number => index.get(k) as number;
  const bytes: number[] = [0x80, group(true, true).length + group(true, false).length, group(true, false).length, group(false, false).length];
  bytes.push(...compact(staticKeys.length));
  for (const k of staticKeys) bytes.push(...base58.decode(k));
  bytes.push(...base58.decode(blockhash));
  bytes.push(...compact(ixs.length));
  for (const ix of ixs) {
    bytes.push(at(ix.program), ...compact(ix.accounts.length), ...ix.accounts.map((a) => at(a.key)), ...compact(ix.data.length), ...ix.data);
  }
  bytes.push(...compact(lookups.length));
  for (const l of lookups) bytes.push(...base58.decode(l.address), ...compact(l.writable.length), ...l.writable, ...compact(l.readonly.length), ...l.readonly);
  return { message: Uint8Array.from(bytes), tablesUsed: lookups.map((l) => l.address) };
}

const acc = (key: string, signer: boolean, writable: boolean): SolanaApiAccount => ({ key, signer, writable });
const ix = (program: string, accounts: SolanaApiAccount[], data: number[]): SolanaApiInstruction => ({ program, accounts, data: Uint8Array.from(data) });
const randomIndex = (n: number): number => {
  const u = new Uint32Array(1);
  globalThis.crypto.getRandomValues(u);
  return (u[0] as number) % n;
};
const isCreate = (x: SolanaApiInstruction): boolean => x.program === SOLANA_ATA_PROGRAM && x.accounts.length === 6 && (x.data.length === 0 || (x.data.length === 1 && x.data[0] === 1));
const isClose = (x: SolanaApiInstruction): boolean => (x.program === SOLANA_TOKEN_PROGRAM || x.program === SOLANA_TOKEN_2022_PROGRAM) && x.data.length === 1 && x.data[0] === 9 && x.accounts.length === 3;

export type SolanaAssembleChain = {
  /** From readSolanaBlockhash: the device's own finalized read. */
  readonly blockhash: string;
  readonly lastValidBlockHeight: number;
  /** The lookup tables the device read itself, by address. A table the build names that is missing or deactivated here is not used. */
  readonly tables: Readonly<Record<string, SolanaLookupTable>>;
  /** The token's program, from the device's own mint read. */
  readonly tokenProgram: string;
};
export type SolanaAssembleOptions = {
  /** Token-2022 mints the device read as holding a transfer fee: an account of one gets its withheld fees harvested before its close. */
  readonly transferFeeMints?: readonly string[];
  /** Tip account choice, for tests; random otherwise. */
  readonly pick?: (n: number) => number;
};
export type SolanaAssembled = {
  /** The unsigned wire: compact-u16 1, 64 zero bytes for W_k's signature, then the message. */
  readonly wire: Uint8Array;
  readonly message: Uint8Array;
  readonly size: number;
  readonly lastValidBlockHeight: number;
  readonly cuLimit: number;
  readonly cuPrice: bigint;
  /** The tables the message loads keys from. */
  readonly tablesUsed: readonly string[];
};

/** The v0 transaction for one wallet from a build answer, on the device's own blockhash and tables. Refuses (SolanaBuildError "too_large") over 1,232 bytes. */
export function assembleSolanaSwap(req: SolanaBuildRequest, build: SolanaJupiterBuild, chain: SolanaAssembleChain, opts: SolanaAssembleOptions = {}): SolanaAssembled {
  const w = req.wallet;
  if (!isKey(w) || !isKey(req.token)) throw new Error("the wallet and the token must be addresses");
  if (!isKey(chain.blockhash) || !Number.isSafeInteger(chain.lastValidBlockHeight) || chain.lastValidBlockHeight <= 0) throw new Error("the blockhash must be the device's own read");
  if (chain.tokenProgram !== SOLANA_TOKEN_PROGRAM && chain.tokenProgram !== SOLANA_TOKEN_2022_PROGRAM) throw new Error("the token program must be Token or Token-2022");
  const pick = opts.pick ?? randomIndex;
  const fee = new Set(opts.transferFeeMints ?? []);
  const cuLimit = solanaRouteCuCap(build.swap.data);
  const head = [ix(SOLANA_COMPUTE_BUDGET_PROGRAM, [], [2, ...u32le(cuLimit)]), ix(SOLANA_COMPUTE_BUDGET_PROGRAM, [], [3, ...u64le(build.cuPrice)])];
  // The accounts the setup creates for the wallet, and the buy's output account, which stays open.
  const created = build.setup.filter((x) => isCreate(x) && x.accounts[2]?.key === w).map((x) => ({ acc: (x.accounts[1] as SolanaApiAccount).key, mint: (x.accounts[3] as SolanaApiAccount).key, tp: (x.accounts[5] as SolanaApiAccount).key }));
  const output = req.side === "buy" ? solanaAta(w, req.token, chain.tokenProgram) : null;
  const pre = [...build.setup];
  if (output && !created.some((c) => c.acc === output)) {
    pre.push(ix(SOLANA_ATA_PROGRAM, [acc(w, true, true), acc(output, false, true), acc(w, false, false), acc(req.token, false, false), acc(SOLANA_SYSTEM_PROGRAM, false, false), acc(chain.tokenProgram, false, false)], [1]));
  }
  const closedLater = new Set([build.cleanup, ...build.other].filter((x): x is SolanaApiInstruction => !!x && isClose(x)).map((x) => (x.accounts[0] as SolanaApiAccount).key));
  const closes: SolanaApiInstruction[] = [];
  for (const c of created) {
    if (c.acc === output || closedLater.has(c.acc) || closes.some((x) => x.accounts[0]?.key === c.acc)) continue;
    if (c.tp !== SOLANA_TOKEN_PROGRAM && c.tp !== SOLANA_TOKEN_2022_PROGRAM) continue; // S13 refuses a create under any other program
    if (c.tp === SOLANA_TOKEN_2022_PROGRAM && fee.has(c.mint)) closes.push(ix(SOLANA_TOKEN_2022_PROGRAM, [acc(c.mint, false, true), acc(c.acc, false, true)], [26, 4]));
    closes.push(ix(c.tp, [acc(c.acc, false, true), acc(w, false, true), acc(w, true, false)], [9]));
  }
  const tips = [
    ix(SOLANA_SYSTEM_PROGRAM, [acc(w, true, true), acc(SOLANA_SENDER_TIP_ACCOUNTS[pick(SOLANA_SENDER_TIP_ACCOUNTS.length)] as string, false, true)], [...u32le(2), ...u64le(SOLANA_SENDER_TIP)]),
    ix(SOLANA_SYSTEM_PROGRAM, [acc(w, true, true), acc(SOLANA_JITO_TIP_ACCOUNTS[pick(SOLANA_JITO_TIP_ACCOUNTS.length)] as string, false, true)], [...u32le(2), ...u64le(SOLANA_JITO_TIP)]),
  ];
  const ixs = [...head, ...pre, build.swap, ...closes, ...(build.cleanup ? [build.cleanup] : []), ...build.other, ...tips];
  const tables = build.tables.flatMap((address) => {
    const t = Object.hasOwn(chain.tables, address) ? chain.tables[address] : undefined;
    return t && solanaTableIsActive(t) ? [{ address, table: t }] : [];
  });
  const { message, tablesUsed } = solanaCompileV0(w, ixs, chain.blockhash, tables);
  const wire = new Uint8Array(1 + 64 + message.length);
  wire[0] = 1;
  wire.set(message, 65);
  if (wire.length > SOLANA_MAX_TX_BYTES) throw new SolanaBuildError("too_large", `${wire.length} bytes > ${SOLANA_MAX_TX_BYTES}`);
  return { wire, message, size: wire.length, lastValidBlockHeight: chain.lastValidBlockHeight, cuLimit, cuPrice: build.cuPrice, tablesUsed };
}

// ---------------------------------------------------------------------------------------------------------------
// The teardown frames (row M1.4; 06c §3.1 S-4, S-5), built after the full sell has landed, from solanaTeardownPlan
// over the device's own reads; checkSolanaTeardown judges them before they are signed. S-4: per token account the plan
// closes, HarvestWithheldTokensToMint (mint, account) right before it when the account has Token-2022's transfer-fee
// extension, then CloseAccount (account, the wallet, the wallet). S-5: close_user_volume_accumulator under each pump
// program whose volume account the plan closes. S-4 and S-5 are separate frames, so a pump change that breaks S-5 never
// holds back the token closes; S-4 splits into more frames when one would pass 1,232 bytes. No tips: a teardown is
// never raced. Each frame asks only the compute it uses (SOLANA_TEARDOWN_CU), at the caller's price.
// ---------------------------------------------------------------------------------------------------------------

/** The teardown frames for one wallet; empty when the plan closes nothing. */
export function buildSolanaTeardown(wallet: string, plan: SolanaTeardownPlan, chain: { blockhash: string; lastValidBlockHeight: number }, opts: { cuPrice?: bigint } = {}): SolanaAssembled[] {
  if (!isKey(wallet)) throw new Error("the wallet must be an address");
  if (!isKey(chain.blockhash) || !Number.isSafeInteger(chain.lastValidBlockHeight) || chain.lastValidBlockHeight <= 0) throw new Error("the blockhash must be the device's own read");
  const price = opts.cuPrice ?? 0n;
  if (typeof price !== "bigint" || price < 0n) throw new Error("the compute unit price must be a bigint of at least 0");
  const cuPrice = price < SOLANA_CU_PRICE_MAX ? price : SOLANA_CU_PRICE_MAX;
  const frame = (body: SolanaApiInstruction[], cu: number): SolanaAssembled => {
    const cuLimit = 2 * SOLANA_TEARDOWN_CU.budget + cu;
    const head = [ix(SOLANA_COMPUTE_BUDGET_PROGRAM, [], [2, ...u32le(cuLimit)]), ...(cuPrice > 0n ? [ix(SOLANA_COMPUTE_BUDGET_PROGRAM, [], [3, ...u64le(cuPrice)])] : [])];
    const { message, tablesUsed } = solanaCompileV0(wallet, [...head, ...body], chain.blockhash, []);
    const wire = new Uint8Array(1 + 64 + message.length);
    wire[0] = 1;
    wire.set(message, 65);
    if (wire.length > SOLANA_MAX_TX_BYTES) throw new SolanaBuildError("too_large", `${wire.length} bytes > ${SOLANA_MAX_TX_BYTES}`);
    return { wire, message, size: wire.length, lastValidBlockHeight: chain.lastValidBlockHeight, cuLimit, cuPrice, tablesUsed };
  };
  const out: SolanaAssembled[] = [];
  // S-4, packed greedily: an account's harvest and close never split across frames.
  let body: SolanaApiInstruction[] = [];
  let cu = 0;
  for (const h of plan.close) {
    if (h.kind !== "token") continue;
    const group = [
      ...(h.harvest ? [ix(SOLANA_TOKEN_2022_PROGRAM, [acc(h.mint, false, true), acc(h.address, false, true)], [26, 4])] : []),
      ix(h.program, [acc(h.address, false, true), acc(wallet, false, true), acc(wallet, true, false)], [9]),
    ];
    const groupCu = SOLANA_TEARDOWN_CU.close + (h.harvest ? SOLANA_TEARDOWN_CU.harvest : 0);
    if (body.length) {
      try {
        frame([...body, ...group], cu + groupCu);
      } catch (e) {
        if (!(e instanceof SolanaBuildError && e.code === "too_large")) throw e;
        out.push(frame(body, cu));
        body = [];
        cu = 0;
      }
    }
    body.push(...group);
    cu += groupCu;
  }
  if (body.length) out.push(frame(body, cu));
  // S-5.
  const volumes = plan.close.filter((h) => h.kind === "volume");
  if (volumes.length) {
    out.push(frame(volumes.map((h) => ix(h.program, [acc(wallet, true, true), acc(h.address, false, true), acc(solanaEventAuthority(h.program), false, false), acc(h.program, false, false)], [...SOLANA_CLOSE_VOLUME_ACCUMULATOR])), volumes.length * SOLANA_TEARDOWN_CU.volume));
  }
  return out;
}

/** The most accounts api.mainnet-beta.solana.com reads back in one simulation ("Too many accounts provided; max 4", 2026-11-02). */
export const SOLANA_SIMULATE_ACCOUNTS_MAX = 4;

/**
 * One provider's simulation of one teardown frame (sigVerify false, replaceRecentBlockhash true, at `confirmed`),
 * reading back the wallet and every given address: one call per group of three addresses with the wallet. Each answer
 * is hostile: shape-checked, and every call must report the same wallet lamports; the first error is returned as err.
 */
export async function simulateSolanaTeardown(rpc: SolanaRpc, wire: Uint8Array, wallet: string, addresses: readonly string[]): Promise<SolanaTeardownSimulation> {
  const lamports = (a: unknown, what: string): bigint | null => {
    if (a === null) return null;
    const v = obj(a, what).lamports;
    if (typeof v !== "number" || !Number.isSafeInteger(v) || v < 0) return bad(`${what}.lamports is not a safe integer`);
    return BigInt(v);
  };
  const per = SOLANA_SIMULATE_ACCOUNTS_MAX - 1;
  const accounts: Record<string, bigint | null> = {};
  let walletAfter: bigint | null = null;
  for (let i = 0; i === 0 || i < addresses.length; i += per) {
    const group = [wallet, ...addresses.slice(i, i + per)];
    const r = obj(await rpc("simulateTransaction", [base64.encode(wire), { encoding: "base64", sigVerify: false, replaceRecentBlockhash: true, commitment: "confirmed", accounts: { addresses: group, encoding: "base64" } }]), "simulateTransaction");
    const v = obj(r.value, "simulateTransaction.value");
    if (v.err !== null && v.err !== undefined) return { err: v.err, wallet: 0n, accounts: {} };
    const list = arr(v.accounts, "simulateTransaction.value.accounts", group.length);
    if (list.length !== group.length) bad(`the simulation read back ${list.length} of ${group.length} accounts`);
    const w = lamports(list[0], "the wallet");
    if (w === null || (walletAfter !== null && w !== walletAfter)) bad("the simulations disagree on the wallet");
    walletAfter = w;
    group.slice(1).forEach((x, j) => {
      accounts[x] = lamports(list[j + 1], x);
    });
  }
  return { err: null, wallet: walletAfter as bigint, accounts };
}

