  "orders.set": obj({ orders: arr(obj({ order_id: str, group_id: str, kind: orderKind, state: orderState })) }),
  "orders.cancel": obj({ orders: arr(obj({ order_id: str, state: orderState })), txs }),
  return: obj({ stage: oneOf(RETURN), txs }),
  "withdraw.open": open,
  "signin.open": open,
  "backup.open": open,
  "export.open": open,
  signout: open,
